export class MessageType {

  static CREATE = 0;
  static CREATE_MESH = 1;
  static TRANSFORM = 2;
  static REMOVE = 3;
  static UPDATE = 4;
  static UPDATE_MESH = 5;
  static COLOR = 6;
  static CREATE_GRANULAR = 7;
  static UPDATE_GRANULAR = 8;
  static AGX_ARCHIVE = 9;
  static WEB_DEBUGGER_VERSION = 10;

  static typeMap = {
    CREATE: MessageType.CREATE,
    CREATE_MESH: MessageType.CREATE_MESH,
    TRANSFORM: MessageType.TRANSFORM,
    REMOVE: MessageType.REMOVE,
    UPDATE: MessageType.UPDATE,
    UPDATE_MESH: MessageType.UPDATE_MESH,
    COLOR: MessageType.COLOR,
    CREATE_GRANULAR: MessageType.CREATE_GRANULAR,
    UPDATE_GRANULAR: MessageType.UPDATE_GRANULAR,
    AGX_ARCHIVE: MessageType.AGX_ARCHIVE,
    WEB_DEBUGGER_VERSION: MessageType.WEB_DEBUGGER_VERSION
  };

  static stringToIndex: { [key: string]: number } = Object.entries(MessageType.typeMap)
    .reduce((acc: { [key: string]: number }, [key, value]) => {
      acc[key.toLowerCase()] = value;
      return acc;
    }, {});

  static indexToString: { [key: number]: string } = Object.entries(MessageType.typeMap)
    .reduce((acc: { [key: number]: string }, [key, value]) => {
      acc[value] = key.toLowerCase();
      return acc;
    }, {});

  static getIndex(name: string): number | null {
    return MessageType.stringToIndex[name.toLowerCase()] ?? null;
  }

  static getString(index: number): string | null {
    return MessageType.indexToString[index] ?? null;
  }
}