import { decode, encode } from "@msgpack/msgpack";
import { ZstdCodec } from 'zstd-codec';
import { PlaybackManager } from "./PlaybackManager";
import { ObjectManager } from "./ObjectManager";
import { UIManager } from "./UIManager";
import { MessageType } from "../utils/MessageType";
import { getWebDebuggerVersion } from "../version";

/// Manages WebSocket connections, message handling, and communication with the server.
export class WebSocketManager {
  
  socket: WebSocket | null = null;
  playbackMgr: PlaybackManager;
  objectMgr: ObjectManager;
  socketPort = 9001; // Default port
  socketHost = "localhost"; // Default host
  m_isConnected = false;
  autoReconnectIntervalId: NodeJS.Timeout | null = null; // Stores the interval ID for auto-reconnection
  autoConnectInterval = 1000; // 500ms interval for auto-reconnect attempts
  numMessagesReceived = 0;
  lastTime = performance.now();
  numBytesReceived = 0;
  enableLogging = false; // non-persistent runtime flag

  uiManager!: UIManager; // Placeholder for UI manager
  simpleDecoder: any = null; // Placeholder for ZstdCodec decoder
  
  constructor(playbackMgr: PlaybackManager, objectMgr: ObjectManager) {
    this.playbackMgr = playbackMgr;
    this.objectMgr = objectMgr;
    this.simpleDecoder = null;

    ZstdCodec.run((zstd: typeof ZstdCodec) => {
      this.simpleDecoder = new (zstd.Simple as { new(): { decompress(buffer: Uint8Array): Uint8Array } })();
    });
  }

  private log(message?: any, ...optionalParams: any[]): void
  {
    if (this.enableLogging)
      console.log(message, ...optionalParams);
  }

  setUIManager(uiManager: UIManager) {
    this.uiManager = uiManager;
  } 

  isConnected() {
    return this.m_isConnected;
  }

  getPort() {
    return this.socketPort;
  }

  getHost() {
    return this.socketHost;
  }

  setPort(port: number): void {
    this.socketPort = port;
    localStorage.setItem('WebDebugger.settings.socketPort', port.toString());
  }

  setHost(host: string): void {
    this.socketHost = host;
    localStorage.setItem('WebDebugger.settings.socketHost', host);

  }

  setEnableLogging(enabled: boolean) { this.enableLogging = enabled; }

  /**
   * Send a command with arbitrary data to the server.
   * Format (MessagePack): [ "cmd", { id: number, name: string, data: any } ]
   */
  sendCommand(name: string, data: any = {}, id?: number) {
    if (!this.socket || this.socket.readyState !== WebSocket.OPEN) {
      console.log("[WebSocket] Cannot send command, socket not open.");
      return false;
    }

    const message = {            
      name,
      data
    };

    try {
      const packed = encode(message);
      this.socket.send(packed);
      this.log("[WebSocket] Sent command:", name, data);
      return true;
    } catch (e) {
      console.error("[WebSocket] Failed to encode/send command:", e);
      return false;
    }
  }

  private onOpen() {
      this.uiManager.clearSidebar();
      this.objectMgr.resetScene();
      this.playbackMgr.resetBufferState();
      this.log("[WebSocket] Connected");
      this.m_isConnected = true;
      this.playbackMgr.setLiveMode(true);
      this.playbackMgr.play();
      this.uiManager.jumpEndBtn.classList.add("active");
      this.uiManager.connectBtn.textContent = "Disconnect";
      this.uiManager.connectBtn.classList.add("active");
      this.stopAutoReconnectInterval(); // If we connected, stop trying to reconnect
      // New: notify UI about connection state change (enables Center button logic when appropriate)
      if (this.uiManager && (this.uiManager as any).handleConnectionStateChanged) {
        (this.uiManager as any).handleConnectionStateChanged(true);
      }
  }

  private onClose() {
    this.log("[WebSocket] Disconnected");
    this.playbackMgr.setLiveMode(false);
    
    if (this.m_isConnected) {
      this.playbackMgr.stop();
    }
    
    this.uiManager.jumpEndBtn.classList.remove("active");
    this.uiManager.connectBtn.textContent = "Connect";
    this.uiManager.connectBtn.classList.remove("active");

    this.m_isConnected = false;

    if (this.uiManager.autoReconnectCheckbox.checked)
      this.startAutoReconnectInterval(); // Start auto-reconnect attempts if enabled

    // New: notify UI to disable Center/Reset when disconnected
    if (this.uiManager && (this.uiManager as any).handleConnectionStateChanged) {
      (this.uiManager as any).handleConnectionStateChanged(false);
    }

  }

  decodeSplitMessage(bufferLike: any) {
    const bytes = bufferLike instanceof Uint8Array ? bufferLike : new Uint8Array(bufferLike);

    const messages = decode(bytes) as any[];                
    
    if (messages.length == 0) 
      return null;
    
    return { packages: messages[0] } as { packages: Uint8Array[] };
  }

  private onMessage(event: any) {
    const startCpuTime = performance.now(); // Start measuring CPU time
    let buffer = new Uint8Array(event.data); // from ArrayBuffer to Uint8Array

    const useCompression = true;
    if (useCompression)
    {
      // Lets check if the first 5 bytes are the magic number (0xcaccafadda) indicating that 
      // we have split the data into several individual compressed messages.      
      if (
        buffer.length >= 5 &&
        buffer[0] === 0xca &&
        buffer[1] === 0xcc &&
        buffer[2] === 0xaf &&
        buffer[3] === 0xad &&
        buffer[4] === 0xda
      ) 
      {
        // Remove first 5 bytes
        buffer = buffer.subarray(5);        
        
        const { numFrames, packages }= this.decodeSplitMessage(buffer) as { numFrames: number, packages: Uint8Array[] };
        // Use numFrames and packages as needed, e.g.:
        // this.log(`Received ${numFrames} frames with ${packages.length} packages`);
        // clear the buffer
        const chunks: Uint8Array[] = [];
        for (const pack of packages) {
          const dec = this.simpleDecoder!.decompress(pack);
          if (!dec) { console.error("decompress failed"); continue; }
          chunks.push(dec);
        }
        buffer = concatUint8Arrays(chunks);        
      }
      else { // no magic number, so it is not a split message

        // Decompress using ZstdCodec
        if (this.simpleDecoder) {
          buffer = this.simpleDecoder.decompress(buffer);
        } else {
          console.error("Zstd simpleDecoder is not initialized.");
          return;
        }
      }
    } // use compression

    const size = buffer.length;

    // decode MessagePack
    const messages = decode(buffer) as any[];                
    
    if (messages.length == 0) 
      return
    
    messages.forEach(pack => {
      const type = pack[0];
      const msg = pack[1];

      if (type === MessageType.AGX_ARCHIVE) {

        const name  = msg[0] ?? "archive.agx";
        const bytes = msg[1] as Uint8Array;     // MessagePack bin -> Uint8Array

        // If saveAGXFile wants an ArrayBuffer:
        //const ab = bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength);

        this.saveAGXFile(name || "archive.agx", bytes);        
      }
       // Verify the version of the Web Debugger on the server and client side.
      else if (type === MessageType.WEB_DEBUGGER_VERSION) {
        const serverVersion = msg[0] as number;
        const clientVersion = getWebDebuggerVersion();
        this.log(`[WebSocket] Web Debugger version - Server: ${serverVersion}, Client: ${clientVersion}`);
        if (serverVersion !== clientVersion) {
          var message = `Protocol version mismatch!\n`;
          message +=    `AGX Dynamics: ${serverVersion}\n`;
          message +=    `Web Debugger: ${clientVersion}\n`;
          message += "\nSome features may not work correctly!";
          this.uiManager.showMessage(message, "Warning");
          console.warn(`[WebSocket] ${message}`);
        }
      }
      else
        this.playbackMgr.handleReceivedMessage(type, msg);
    });

    this.numMessagesReceived++;
    this.numBytesReceived += size;

    // Get current time
    const now = performance.now();
    const elapsed = now - this.lastTime;

    if (elapsed >= 1000) { // 1000 ms = 1 second
      this.log(`Packages per second: ${this.numMessagesReceived} | ${this.numBytesReceived/1024} kB/s`);
      this.numMessagesReceived = 0;
      this.numBytesReceived = 0;
      this.lastTime = now;
    }
  }  
  
  private async saveAGXFile(name: string, data: ArrayBuffer | Uint8Array) {
    
    const suggestedName = name.endsWith(".agx") ? name : `${name}.agx`;
    const bytes = data instanceof ArrayBuffer ? new Uint8Array(data) : data; // both fine
    // Fallback: trigger a download (works everywhere)
    const blob = new Blob([bytes], { type: "application/octet-stream" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url; a.download = suggestedName;
    document.body.appendChild(a); a.click(); a.remove();
    URL.revokeObjectURL(url);
  }

  private onError(error: Event): void {
    this.log('[WebSocket] Error:', error);
  }



  connect() {

    // Do not connect if playback is going on!
    if (this.playbackMgr.isPlaying()) {
      console.warn("[WebSocket] Cannot connect while playback is active. Please pause playback first.");
      return;
    }

    // Prevent multiple connection attempts if one is already in progress or established
    if (this.socket && (this.socket.readyState === WebSocket.OPEN || this.socket.readyState === WebSocket.CONNECTING)) {
      this.log("[WebSocket] Already connected or attempting to connect.");
      return;
    }

    this.log("[WebSocket] Attempting to connect...");
    this.log("[WebSocket] Port:", this.socketPort);
    const address = 'ws://' + this.socketHost + ':' + this.socketPort;
    this.log("[WebSocket] Connecting to:", address);

    let ws: WebSocket;
    try {
      ws = new WebSocket(address);
    } catch (e) {
      // Synchronous creation errors (bad URL etc.) can be caught here
      this.log('[WebSocket] Failed to create WebSocket instance:', e);
      return;
    }

    // Assign only after successful creation
    this.socket = ws;
    this.socket.binaryType = "arraybuffer"; // critical: get raw binary buffer!

    // Attach listeners (using bound arrow functions to avoid multiple rebinds)
    this.socket.addEventListener('open', () => this.onOpen());
    this.socket.addEventListener('close', () => this.onClose());
    this.socket.addEventListener('message', (event) => this.onMessage(event));
    this.socket.addEventListener('error', (error) => this.onError(error));
  } 

  // Function to manually disconnect the WebSocket
  disconnect() {
    this.stopAutoReconnectInterval(); // Stop any auto-reconnect attempts before manual disconnect
    if (this.m_isConnected && this.socket) {
      this.socket.close();
      this.log("[WebSocket] Manually disconnected.");
    } else {
      this.log("[WebSocket] Already disconnected or no socket instance.");
    }
    // UI updates are handled by the 'close' event listener
  }

  startAutoReconnectInterval() {
    
    if (this.m_isConnected || this.autoReconnectIntervalId) {
      return;
    }

    this.log("[AutoReconnect] Starting attempts...");
    this.autoReconnectIntervalId = setInterval(() => {
      if (!this.m_isConnected) { // Double check connection status before attempting
        this.log("[AutoReconnect] Attempting to reconnect...");
        this.connect();
      } else {
        this.stopAutoReconnectInterval(); // Should not happen if isConnected is true, but as a safeguard
      }
    }, this.autoConnectInterval); // Try every half second (500ms)
  }

  // Function to stop auto-reconnect attempts
  stopAutoReconnectInterval() {
    if (this.autoReconnectIntervalId) {
      clearInterval(this.autoReconnectIntervalId);
      this.autoReconnectIntervalId = null;
      this.log("[AutoReconnect] Stopped attempts.");
    }
  }
}

function concatUint8Arrays(chunks: Uint8Array[]): Uint8Array {
  let total = 0;
  for (const c of chunks) total += c.byteLength;
  const out = new Uint8Array(total);
  let off = 0;
  for (const c of chunks) { out.set(c, off); off += c.byteLength; }
  return out;
}
