import * as THREE from 'three';

export class Capsule extends THREE.Group {
  
  material: THREE.Material;
  height: number;
  radius: number;
  /**
   * Creates a capsule shape consisting of a cylinder with hemispherical ends.
   * @param {number} radius - The radius of the capsule.
   * @param {number} height - The height of the cylindrical part of the capsule.
   * @param {THREE.Material} [material] - The material to apply to the capsule.
   * @param {number} [segments=32] - The number of segments for the cylinder and sphere geometry.
   */
  constructor(radius: number, height: number, material: THREE.Material, segments: number) {
      
      super(); 

      this.material = material || new THREE.MeshStandardMaterial({ color: 0x0077ff });
      this.height = height;
      this.radius = radius;
  
      this._createGeometry(segments);
    }

    _createGeometry(segments: number) {
      const { radius, height, material } = this;
  
      // Cylinder
      const cylGeom = new THREE.CylinderGeometry(radius, radius, height, segments);
      const cylinder = new THREE.Mesh(cylGeom, material);
      this.add(cylinder);
  
      // Top Sphere
      const sphereGeom = new THREE.SphereGeometry(radius, segments, segments);
      const top = new THREE.Mesh(sphereGeom, material);
      top.position.y = height / 2;
      this.add(top);
  
      // Bottom Sphere
      const bottom = new THREE.Mesh(sphereGeom, material);
      bottom.position.y = -height / 2;
      this.add(bottom);
    }
      
    setPosition(vec3: THREE.Vector3) {
      this.position.copy(vec3);
    }
  
    setRotation(euler: THREE.Euler) {
      this.rotation.copy(euler);
    }
  
    setScale(x: number, y: number) {
      // Cylinder
      this.children[0].scale.set(x, y, x);
      //sphere+
      this.children[1].scale.set(x, x, x);
      this.children[1].position.y = y/2;
      // sphere-
      this.children[2].scale.set(x, x, x);
      this.children[2].position.y = -y/2;
    }
  
  }
