import { Shapes } from '../utils/Shapes.js';
import { Capsule } from '../components/Capsule.js';
import { Granular } from '../components/Granular.js';
import * as THREE from 'three';

import { SceneManager } from './SceneManager.js';
import { UIManager } from './UIManager.js';
import { HollowCone } from '../components/HollowCone.js';
import { TruncatedCone } from '../components/TruncatedCone.js';


//// Manages 3D objects in the scene, including creation, transformation, and removal.
///
export class ObjectManager {
  
  objects: Map<number, THREE.Object3D>;
  sceneManager: SceneManager;
  uiManager!: UIManager;
  primitiveTesselation: number = 10;

  constructor(sceneManager: SceneManager) {
    this.objects = new Map();    
    this.sceneManager = sceneManager;
    this.sceneManager.setObjectManager(this);
    
  }

  setPrimitiveTesselation(tesselation: number) {
    this.primitiveTesselation = tesselation;
    localStorage.setItem('WebDebugger.settings.primitiveTesselation', tesselation.toString());
  }

  setUIManager(uiManager: UIManager) {
    this.uiManager = uiManager;
  }

  clear() {
    this.objects.clear();
  }
  
  set(uuid: number, object: THREE.Object3D) {
    this.objects.set(uuid, object);
    //console.log("Added object:", uuid, object3D);
  }

  has(uuid: number) {
    return this.objects.has(uuid);
  }

  get(uuid: number) {
    return this.objects.get(uuid);
  }
  empty()
  {
    return this.objects.size === 0;
  }

  removeObject(uuid: number) {
    const obj = this.objects.get(uuid);
    if (obj) {
      this.objects.delete(uuid);
    }
  }
    
  resetScene() {

    this.sceneManager.clear();
    this.clear();
  }


  private createTriMeshGeometry(indices: number[], vertices: number[]) {

    //console.log("Creating trimesh geometry:", indices, vertices);
    const geometry = new THREE.BufferGeometry();

    geometry.setAttribute(
      'position',
      new THREE.Float32BufferAttribute(vertices, 3)
    );
    geometry.setIndex(indices);
    geometry.computeVertexNormals();

    return geometry;
  }


  createShape(msg: any) {
    const { uuid, geometry, color, position, rotation, ...rest } = msg;

    if (!(typeof uuid === 'number'))
    {
      console.log("createShape: Invalid UUID type:", uuid.type);
    }


    //console.log("createShape:", msg);

    if (uuid == undefined)
      return;
    
    if (this.has(uuid)) {
      //console.log("createShape: Object already exists:", uuid);
      return;
    }

    if (geometry === Shapes.TEXT) {
      let textObj = new THREE.Object3D();

      textObj.userData.type = Shapes.TEXT;
      textObj.userData.name = msg.name;
      
      this.set(uuid, textObj);

      this.uiManager.addText(msg.uuid, msg.text);
      return;
    }
  
    const colorObj = new THREE.Color();
    if (color)
      colorObj.setRGB(color[0], color[1], color[2]); // RGB color

    let shapeGeometry: THREE.BufferGeometry | undefined = undefined;
    let shapeMaterial;
    let mesh: THREE.Object3D | null = null;
    let group: THREE.Object3D | null = null;
    let needUpdate = false;
    let shouldUseWireFrameOverlay = true;

    const tesselationRatio = this.primitiveTesselation;
    switch (geometry) {
      case Shapes.SPHERE:
        shapeGeometry = new THREE.SphereGeometry(1 || 1, tesselationRatio, tesselationRatio);
        if (shapeGeometry)
          shapeGeometry.userData.type = Shapes.SPHERE;
        needUpdate = true;
        break;

      case Shapes.BOX:
        shapeGeometry = new THREE.BoxGeometry(1, 1, 1);
        shapeGeometry.userData.type = Shapes.BOX;
        needUpdate = true;
        break;

      case Shapes.CYLINDER:
        shapeGeometry = new THREE.CylinderGeometry(1, 1, 1, tesselationRatio, 2);
        shapeGeometry.userData.type = Shapes.CYLINDER;
        needUpdate = true;
        break;

      case Shapes.CAPSULE:

        shapeMaterial = new THREE.MeshStandardMaterial({
          color: colorObj,
          transparent: true,
          opacity: 0.4,
          depthWrite: false, // Prevent depth sorting issues with wireframe
        });
        group = new Capsule(1, 1, shapeMaterial, tesselationRatio);
        group.userData.type = Shapes.CAPSULE;
        mesh = group; // Just so that it != null
        needUpdate = true;
        break;

      case Shapes.TRUNCATED_CONE:

        shapeMaterial = new THREE.MeshStandardMaterial({
          color: colorObj,
          transparent: true,
          opacity: 0.4,
          depthWrite: true, // Prevent depth sorting issues with wireframe
        });

        // Hollow cone does its own wireframe overlay
        shouldUseWireFrameOverlay = false;

        group = new TruncatedCone(0.2, 0.8, 0.15, shapeMaterial, tesselationRatio);
        group.userData.type = Shapes.TRUNCATED_CONE;
        mesh = group; // Just so that it != null
        needUpdate = true;
        break;


      case Shapes.HOLLOW_CYLINDER:

        shapeMaterial = new THREE.MeshStandardMaterial({
          color: colorObj,
          transparent: true,
          opacity: 0.4,
          depthWrite: true, // Prevent depth sorting issues with wireframe
        });

        // Hollow cone does its own wireframe overlay
        shouldUseWireFrameOverlay = false;

        group = new HollowCone(0.2, 0.2, 0.8, 0.15, shapeMaterial, tesselationRatio);
        group.userData.type = Shapes.HOLLOW_CYLINDER;
        mesh = group; // Just so that it != null
        needUpdate = true;
        break;

      case Shapes.HOLLOW_CONE:

        shapeMaterial = new THREE.MeshStandardMaterial({
          color: colorObj,
          transparent: true,
          opacity: 0.4,
          depthWrite: true, // Prevent depth sorting issues with wireframe
        });
        
        // Hollow cone does its own wireframe overlay
        shouldUseWireFrameOverlay = false;

        group = new HollowCone(0.2, 0.25, 0.8, 0.15, shapeMaterial, tesselationRatio);
        group.userData.type = Shapes.HOLLOW_CONE;
        mesh = group; // Just so that it != null
        needUpdate = true;
        break;


      case Shapes.GRANULAR:

        shapeMaterial = new THREE.MeshStandardMaterial({
          color: colorObj,
          transparent: true,
          opacity: 0.4,
          depthWrite: false, // Prevent depth sorting issues with wireframe
        });

        const granular = new Granular(shapeMaterial, tesselationRatio);
        
        granular.setPosition(msg.position);
        granular.setRadius(msg.size);
        granular.userData.type = Shapes.GRANULAR;
        group = granular;
        mesh = group; // Just so that it != null
        needUpdate = false;
        break;

      case Shapes.CONE:
          shapeGeometry = new THREE.ConeGeometry(1, 1, tesselationRatio, 2);
          shapeGeometry.userData.type = Shapes.CONE;
          needUpdate = true;
          break;

      case Shapes.MESH:
        shapeGeometry = this.createTriMeshGeometry(msg.indices, msg.vertices);
        shapeGeometry.userData.type = Shapes.MESH;
        shouldUseWireFrameOverlay = false;

        shapeMaterial = new THREE.MeshStandardMaterial({
          color: colorObj,
          wireframe: true
        });
        break;
        
      case Shapes.HEIGHTFIELD:
          shapeGeometry = this.createTriMeshGeometry(msg.indices, msg.vertices);
          shapeGeometry.userData.type = Shapes.HEIGHTFIELD;
          shouldUseWireFrameOverlay = false;

          shapeMaterial = new THREE.MeshStandardMaterial({
            color: colorObj,
            wireframe: true
          });
          break;
          
      case Shapes.LINE:
        const pointA = new THREE.Vector3(msg.size[0], msg.size[1],msg.size[2]); 
        const pointB = new THREE.Vector3(msg.size[3], msg.size[4],msg.size[5]);
        shapeGeometry = new THREE.BufferGeometry().setFromPoints([pointA, pointB]);    
        shapeMaterial = new THREE.LineBasicMaterial({ color: colorObj });
        shouldUseWireFrameOverlay = false;

        mesh = new THREE.Line(shapeGeometry, shapeMaterial);

        shapeGeometry.userData.type = Shapes.LINE;
        break;
      
      default:
        console.warn("Unknown geometry type:", geometry);
        return;
    }
  
    // Semi-transparent fill material
    if (!shapeMaterial) {
      if (false) {
        shapeMaterial = new THREE.MeshPhysicalMaterial({
          color: 0xffccaa,
          metalness: 1.0,
          roughness: 0.25,
          clearcoat: 0.8,
          transmission: 0.9, // For glass-like surfaces
          ior: 1.5
        });
      } else {
        shapeMaterial = new THREE.MeshStandardMaterial({
          color: colorObj,
          transparent: true,
          opacity: 0.4,
          depthWrite: false, // Prevent depth sorting issues with wireframe
        });
      }
    }
  
    if (!mesh) {
      mesh = new THREE.Mesh(shapeGeometry, shapeMaterial);
      //mesh.castShadow = true;
      //mesh.receiveShadow = true;
    }

    if (!group) {
      group = new THREE.Object3D();
      group.add(mesh);
    }
  
    // Wireframe overlay
    if (shouldUseWireFrameOverlay)
    {

      addWireframeOverlay(mesh, colorObj)

      /*
      const edges = new THREE.EdgesGeometry(shapeGeometry);
      const lineMaterial = new THREE.LineBasicMaterial({ color: colorObj });
      
      lineMaterial.depthTest = false;
      lineMaterial.polygonOffset = true;

      const wireframe = new THREE.LineSegments(edges, lineMaterial);
      group.add(wireframe);*/
    }

    // Set initial position and rotation (remap position and quaternion)
    this.applyWorldToViewerTransform(group, rotation, position, true);
    
    this.sceneManager.add(group);
    
    // Add user data for easy access later
    group.userData.type = geometry;
    group.userData.objectType = msg.objectType; // Add object type to userData
    group.userData.uuid = uuid; // Store the UUID in userData for easy access later
    group.userData.size = rest.size || undefined; // Store size in userData for easy access later
    group.userData.color = colorObj.toArray(); // Store color in userData for easy access later 
    group.userData.name = msg.name;
    this.set(uuid, group);
  
    if (needUpdate)
      this.updateShape(msg);

    this.uiManager.addToSidebar(uuid, msg.objectType, msg.name);
  }
    

  transformShape(msg: any, shouldApplyWorldToViewerTransform: boolean = true) 
  {
    if (!this.has(msg.uuid)) {
      return;
    }

    const obj = this.get(msg.uuid);
    if (!obj) {
      console.log('Object not found:', msg.uuid);
      return;
    }

    //if (obj.userData.type != Shapes.LINE)
      this.applyWorldToViewerTransform(obj, msg.rotation, msg.position, shouldApplyWorldToViewerTransform);
  }

  /* Helper function to apply world to viewer transform */
  applyWorldToViewerTransform(obj: THREE.Object3D, rotation: any, position: any, shouldApplyWorldToViewerTransform: boolean = false) 
  {
    if (rotation) 
    {
      if (shouldApplyWorldToViewerTransform)
      {
        if (Array.isArray(rotation)) {
          const worldQuat = new THREE.Quaternion(...rotation);
          obj.quaternion.copy(this.sceneManager.worldToViewerQuaternion(worldQuat));
        } else if (rotation instanceof THREE.Quaternion) {
          obj.quaternion.copy(this.sceneManager.worldToViewerQuaternion(rotation));
        } else {
          obj.quaternion.copy(rotation);
        }
      } else {
        if (Array.isArray(rotation)) {
          const worldQuat = new THREE.Quaternion(...rotation);
          obj.quaternion.copy(worldQuat);
        } else {
          obj.quaternion.copy(rotation);
        }      
      }
    }

    if (position)
    {
      if (shouldApplyWorldToViewerTransform) {
        const viewerPos = this.sceneManager.worldToViewer(new THREE.Vector3(...position));
        obj.position.copy(viewerPos);
      }
      else
        obj.position.copy(new THREE.Vector3(...position));
    }
  }
  removeShape(uuid: number) {
    const obj = this.get(uuid);
    if (!obj)
      return;

    this.sceneManager.remove(obj);

    const name = obj.userData.name;
    this.removeObject(uuid);

    this.uiManager.removeFromSidebar(uuid, name);

    if (obj.userData.type == Shapes.TEXT) {
      this.uiManager.removeText(uuid);
    }
  }

  /*
  Update shape properties like size, text, etc.
  */
  updateShape(msg: any) {

    const obj = this.get(msg.uuid);
    if (!obj) {
      //console.log('updateShape1: Object not found:', msg.uuid);
      return;
    }

    //console.log("Updating shape:", msg);
    const type = obj.userData.type;
    if (obj.userData.name == undefined || obj.userData.name != msg.name) {
      this.uiManager.updateName(msg.uuid, msg.name);
      obj.userData.name = msg.name;
    }

    switch (type) {
      
      case (Shapes.TEXT):
        this.uiManager.setText(msg.uuid, msg.text);
        obj.userData.text = msg.text; // Store text in userData for easy access later
        break;

      case(Shapes.SPHERE):
        obj.scale.set(msg.size[0], msg.size[0], msg.size[0]); // Scale the sphere
        obj.userData.size = msg.size;
        break;

      case (Shapes.BOX):
        obj.scale.set(msg.size[0]*2, msg.size[1]*2, msg.size[2]*2); // Scale the Box
        obj.userData.size = msg.size;

        break;

      case (Shapes.CYLINDER):
        obj.scale.set(msg.size[0], msg.size[1], msg.size[0]); // Scale the Cylinder
        obj.userData.size = msg.size;
        break;

      case(Shapes.CAPSULE):
        if (msg.position) {
          const viewerPos = this.sceneManager.worldToViewer(new THREE.Vector3(...msg.position));
          (obj as Capsule).setPosition(viewerPos);
        }
        (obj as Capsule).setScale(msg.size[0], msg.size[1]); // Scale the Capsule
        obj.userData.size = msg.size;
        break;

      case(Shapes.HOLLOW_CONE):
        if (msg.position) {
          const viewerPos = this.sceneManager.worldToViewer(new THREE.Vector3(...msg.position));
          (obj as HollowCone).setPosition(viewerPos);
        }
        (obj as HollowCone).setSize(msg.size[0], msg.size[1], msg.size[2], msg.size[3]); // Set the size
        obj.userData.size = msg.size;
        break;

      case(Shapes.TRUNCATED_CONE):
        if (msg.position) {
          const viewerPos = this.sceneManager.worldToViewer(new THREE.Vector3(...msg.position));
          (obj as TruncatedCone).setPosition(viewerPos);
        }
        (obj as TruncatedCone).setSize(msg.size[0], msg.size[1], msg.size[2]); // Set the size
        obj.userData.size = msg.size;
        break;

      case(Shapes.HOLLOW_CYLINDER):
        if (msg.position) {
          const viewerPos = this.sceneManager.worldToViewer(new THREE.Vector3(...msg.position));
          (obj as HollowCone).setPosition(viewerPos);
        }
        (obj as HollowCone).setSize(msg.size[0], msg.size[0], msg.size[1], msg.size[2]); // Set the size
        obj.userData.size = msg.size;
        break;

      case (Shapes.CONE):
        obj.scale.set(msg.size[0], msg.size[1], msg.size[0]); // Scale the Cone
        obj.userData.size = msg.size;
        break;

      case (Shapes.MESH):
        //console.log("Updating mesh");
        // Do nothing for trimesh, as it doesn't have a size property
        //obj.scale.set(msg.size[1], msg.size[1], msg.size[2]); // Scale the Cone
        break;

      case (Shapes.GRANULAR):
      {
        (obj as Granular).setRadius(msg.size);
        if (msg.position) {
          // We have to loop through all particles and update their position
          if (this.sceneManager.requireWorldToViewerTransform())
          {
            let pos = new THREE.Vector3();
            for (let i = 0; i < msg.position.length; i+=3) {
              pos.x = msg.position[i];
              pos.y = msg.position[i+1];
              pos.z = msg.position[i+2];

              const viewerPos = this.sceneManager.worldToViewer(pos);
              msg.position[i] = viewerPos.x;
              msg.position[i+1] = viewerPos.y;
              msg.position[i+2] = viewerPos.z;
            }
            }
          (obj as Granular).setPosition(msg.position);
        }
        break;
      }

      case (Shapes.HEIGHTFIELD):
      {
        const geometry = (obj.children[0] as THREE.Mesh).geometry; // Assuming the first child is the mesh
        const positionAttr = geometry.attributes.position;
        // msg.indices contains all the indices that are modified
        // msg.vertices contains the new z values for those indices
        for (let i = 0; i < msg.indices.length; i++) {
          const index = msg.indices[i];
          let x = positionAttr.array[index*3];
          let y = positionAttr.array[index*3+1];
          let newZ = msg.vertices[i];
          positionAttr.setXYZ(index, x, y, newZ);
        }
        positionAttr.needsUpdate = true;
        break;
      }

      case(Shapes.LINE):
      {
        const geometry = (obj.children[0] as THREE.Mesh).geometry; // Assuming the first child is the mesh
        const position = geometry.attributes.position.array;

        obj.userData.size = msg.size;

        const p1 = this.sceneManager.worldToViewer(new THREE.Vector3(msg.size[0], msg.size[1], msg.size[2]));
        const p2 = this.sceneManager.worldToViewer(new THREE.Vector3(msg.size[3], msg.size[4], msg.size[5]));

        position[0] = p1.x;
        position[1] = p1.y;
        position[2] = p1.z;
        position[3] = p2.x
        position[4] = p2.y;
        position[5] = p2.z;
        geometry.attributes.position.needsUpdate = true;
        break;
      }
    }
  }

  setShapeColor(msg: any) {

    const obj = this.get(msg.uuid);
    if (!obj) {
      //console.log('setShapeColor: Object not found:', msg.uuid);
      return;
    }

    if (obj.userData.type == Shapes.TEXT) {
      obj.userData.color = msg.color; // Store color in userData for easy access later
      this.uiManager.setTextColor(msg.uuid, msg.color);
      return;
    }

    if (msg.color) {
      const colorObj = new THREE.Color();
      if (Array.isArray(msg.color)) {
        colorObj.setRGB(msg.color[0], msg.color[1], msg.color[2]);
      } else {
        // Assuming msg.color is a hexadecimal string or number
        colorObj.set(msg.color);
      }

      obj.userData.color = colorObj.toArray(); // Store color in userData for easy access later
      obj.traverse((child) => {
        if ((child as THREE.Mesh).material && (child as THREE.Mesh).material instanceof THREE.Material && ((child as THREE.Mesh).material as any).color) {
          ((child as THREE.Mesh).material as any).color.copy(colorObj);
        }
      });
    }
  }  

} // ObjectManager

function addWireframeOverlay(obj: THREE.Object3D, color: THREE.Color) {
  if (obj instanceof THREE.Mesh && obj.geometry) {
    const edges = new THREE.EdgesGeometry(obj.geometry);
    const lineMaterial = new THREE.LineBasicMaterial({ color });
    const wireframe = new THREE.LineSegments(edges, lineMaterial);
    obj.add(wireframe);
  } else if (obj instanceof THREE.Group) {
    obj.children.forEach(child => {
      if (child instanceof THREE.Mesh && child.geometry) {
        const edges = new THREE.EdgesGeometry(child.geometry);
        const lineMaterial = new THREE.LineBasicMaterial({ color });
        const wireframe = new THREE.LineSegments(edges, lineMaterial);
        child.add(wireframe); // or child.add(wireframe) if you want wireframe attached to mesh
      }
    });
  }
}
