  // Add event listener for the new sim-time-input field
  private initSimTimeInput() {
    this.simTimeInputEl.addEventListener('change', (e) => {
      const t = parseFloat((e.target as HTMLInputElement).value);
      const slider = this.timeLineSlider;
      const minTime = parseFloat(slider.min);
      const maxTime = parseFloat(slider.max);

      if (!isNaN(t) && t >= minTime && t <= maxTime) {
        this.playbackManager.jumpToTime(t); // jumpToTime updates currentTime, animate loop updates input display
      } else {
        (e.target as HTMLInputElement).value = this.playbackManager.getCurrentTime().toFixed(2); // Reset to current currentTime if invalid
        console.warn(`Invalid time input: ${t}. Must be between ${minTime.toFixed(2)} and ${maxTime.toFixed(2)}.`);
      }
    });

    // Optional: Update time on Enter key press as well, not just on blur (change event)
    this.simTimeInputEl.addEventListener('keypress', (e) => {
      if (e.key === 'Enter') {
        const t = parseFloat((e.target as HTMLInputElement).value);
        const slider = this.timeLineSlider;
        const minTime = parseFloat(slider.min);
        const maxTime = parseFloat(slider.max);

        if (!isNaN(t) && t >= minTime && t <= maxTime) {
          this.playbackManager.jumpToTime(t);
          this.simTimeInputEl.blur(); // Remove focus from input
        } else {
          (e.target as HTMLInputElement).value = this.playbackManager.getCurrentTime().toFixed(2); // Reset to current currentTime if invalid
          console.warn(`Invalid time input: ${t}. Must be between ${minTime.toFixed(2)} and ${maxTime.toFixed(2)}.`);
        }
      }
    });
  }
  removeFromSidebar(uuid: number | string, name: string) {

    // Remove from sidebar
    const id = `item-${uuid}`;
    const item = document.getElementById(id);
    if (item && item.parentElement) {
      item.parentElement.removeChild(item);
    }
  }

  updateName(uuid: number | string, name: string) {
    // Find the sidebar item
    const id = `item-${uuid}`;
    const item = document.getElementById(id);
    if (!item) return;
    // Find the current name in the sidebar (after the checkbox)
    const visCheckbox = item.querySelector('input[type="checkbox"]');
    // The text node is the second child
    const textNode = item.childNodes[1];
    if (textNode && textNode.nodeType === Node.TEXT_NODE) {
      const currentText = textNode.textContent || '';
      // Extract the name part (before the uuid in parentheses)
      const match = currentText.match(/^(.*) \([^)]+\)$/);
      const currentName = match ? currentText[1] : currentText;
      if (currentName !== name) {
        textNode.textContent = `${name} (${uuid})`;
      }
    }
  }
  addToSidebar(uuid: number | string, objectType: number, name: string) {
    // Ensure uuid is a number for Map lookup
    const uuidNum = typeof uuid === 'number' ? uuid : parseInt(uuid, 10);
    const groupId = ObjectType.getString(objectType) + "-group";
    const group = document.getElementById(groupId);
    const item = document.createElement('div');
    item.classList.add('tree-item');
    item.textContent = `${name} (${uuid})`;
    item.id = `item-${uuid}`;    
    
    // --- Add visibility checkbox ---
    const visCheckbox = document.createElement('input');
    visCheckbox.type = 'checkbox';
    visCheckbox.checked = true;
    visCheckbox.style.marginRight = '6px';
    visCheckbox.title = 'Toggle visibility';
    
    // Stop click propagation on checkbox to prevent item selection
    visCheckbox.addEventListener('click', (e) => {
      e.stopPropagation();
    });
    
    visCheckbox.addEventListener('change', (e) => {
      e.stopPropagation(); // Prevent the click from bubbling to the item
      // Find the Three.js object and set its visibility
      const obj = this.objectManager.get(uuidNum);
      if (obj) obj.visible = visCheckbox.checked;
      
      // Update parent group checkbox state
      const groupType = ObjectType.getString(objectType);
      const groupCheckbox = document.getElementById(`vis-${groupType}`) as HTMLInputElement;
      if (groupCheckbox) {
        const groupElement = document.getElementById(`${groupType}-group`);
        if (groupElement) {
          const allItemCheckboxes = Array.from(groupElement.querySelectorAll('.tree-item input[type="checkbox"]')) as HTMLInputElement[];
          const allChecked = allItemCheckboxes.every(cb => cb.checked);
          const noneChecked = allItemCheckboxes.every(cb => !cb.checked);
          
          if (allChecked) {
            groupCheckbox.checked = true;
            groupCheckbox.indeterminate = false;
          } else if (noneChecked) {
            groupCheckbox.checked = false;
            groupCheckbox.indeterminate = false;
          } else {
            groupCheckbox.indeterminate = true;
          }
        }
      }
      
      // Update Scene checkbox state
      const sceneCheckbox = document.getElementById('vis-scene') as HTMLInputElement;
      if (sceneCheckbox) {
        const allGroupCheckboxes = Array.from(document.querySelectorAll('.group-vis-checkbox'))
          .filter(cb => cb.id !== 'vis-scene') as HTMLInputElement[];
        const allChecked = allGroupCheckboxes.every(cb => cb.checked && !cb.indeterminate);
        const noneChecked = allGroupCheckboxes.every(cb => !cb.checked && !cb.indeterminate);
        
        if (allChecked) {
          sceneCheckbox.checked = true;
          sceneCheckbox.indeterminate = false;
        } else if (noneChecked) {
          sceneCheckbox.checked = false;
          sceneCheckbox.indeterminate = false;
        } else {
          sceneCheckbox.indeterminate = true;
        }
      }
    });
    // Insert checkbox before text
    item.textContent = '';
    item.appendChild(visCheckbox);
    item.appendChild(document.createTextNode(`${name} (${uuidNum})`));    // --- End visibility checkbox ---
    item.addEventListener('click', (e) => {
      // Prevent click on checkbox from selecting
      if (e.target === visCheckbox) return;
      if (this.sceneManager.selectObjectByUUID(uuidNum)) {
        this.focusBtn.disabled = false;
        this.followCheckbox.disabled = false;
      } else {
        this.focusBtn.disabled = true;
        this.followCheckbox.disabled = true;
        this.followCheckbox.checked = false;
      }
    });
    if (group) {
      group.appendChild(item);
    }
  } 
  
