import * as THREE from 'three';

export class Granular extends THREE.Group {
    
    material: THREE.Material;
    sphereMesh: THREE.Mesh | null;
    /**
     * Creates a granular shape consisting of multiple spheres.
     * @param {THREE.Material} material - The material to apply to the spheres.
     * @param {number} segments - The number of segments for the sphere geometry.
     */
    constructor(material: THREE.Material, segments: number) {
      
      super(); 

      this.material = material;
      this.sphereMesh = null;
      this._createGeometry(segments);
    }

    _createGeometry(segments: number) {

      const sphereGeom = new THREE.SphereGeometry(1.0, segments, segments);
      this.sphereMesh = new THREE.Mesh(sphereGeom, this.material);     
    }
      
    _updateChildren(numSpheres: number)
    {
      // Too few spheres, add more
      while(this.children.length < numSpheres) {
        if (this.sphereMesh) {
          const sphere = this.sphereMesh.clone();        
          this.add(sphere);
        }
      }
      // Too many spheres, remove some
      while(this.children.length > numSpheres) {
        const sphere = this.children.pop();
        if (sphere) {
          this.remove(sphere);
        }
      }
    }

    setPosition(positionArray: number[]): void {
      this._updateChildren(positionArray.length/3);

      let i = 0;
      this.children.forEach(element => {
        element.position.set(positionArray[i*3], positionArray[i*3 + 1],
          positionArray[i*3 + 2]);  
        i++;
      });

    }
  
    setRadius(radiusArray: number[]): void {
      this._updateChildren(radiusArray.length);

      let i = 0;
      this.children.forEach((element: THREE.Object3D) => {
      element.scale.set(radiusArray[i], radiusArray[i], radiusArray[i]);  
      i++;
      });
    }  
  }
