import './style.css';
import * as THREE from 'three';

import { WebSocketManager } from './core/WebSocketManager.js';
import { UIManager } from './core/UIManager.js';
import { ObjectManager } from './core/ObjectManager.js';
import { SceneManager } from './core/SceneManager.js';
import { PlaybackManager } from './core/PlaybackManager.js';


const sceneManager = new SceneManager();
(window as any).sceneManager = sceneManager;
const objectManager = new ObjectManager(sceneManager);
const playbackManager = new PlaybackManager(objectManager, sceneManager);
const webSocketManager = new WebSocketManager(playbackManager, objectManager);
playbackManager.setWebSocketManager(webSocketManager);
const uiManager = new UIManager(sceneManager, playbackManager, webSocketManager, objectManager);
sceneManager.setUIManager(uiManager);

  
const targetFPS = 60;
const frameDuration = 1000 / targetFPS; // e.g. ~16.67ms
let lastRenderedTime = 0;

// Add to your main animate() loop:
function animate() {
  requestAnimationFrame(animate);
  const now = performance.now();

  if (sceneManager.isFollowingObject())
    sceneManager.followObject()

  // Do things here
  playbackManager.updateBuffer()

  uiManager.updateCurrentTime(playbackManager.getCurrentTime());

  if (now - lastRenderedTime >= frameDuration) {
    lastRenderedTime = now;

    uiManager.beginStats();
    
    sceneManager.update()
    
    uiManager.endStats();
  }
}

animate();


