import { MessageType } from '../utils/MessageType.js';
import { Shapes } from '../utils/Shapes.js';
import { ObjectType } from '../utils/ObjectType.js';
import { ObjectManager } from './ObjectManager.js';
import { SceneManager } from './SceneManager.js';
import { UIManager } from './UIManager.js';
import { WebSocketManager } from './WebSocketManager.js';
import { encode, decode } from '@msgpack/msgpack';
import { ZstdCodec } from 'zstd-codec';

/// PlaybackManager handles playback of recorded messages, buffering, keyframes, and session saving/loading.
export class PlaybackManager {
  objectManager: ObjectManager;
  sceneManager: SceneManager;
  webSocketManager: WebSocketManager | null = null;
  uiManager: UIManager | null = null;
  
  // Encode storage for messages
  private encodedArena: Uint8Array = new Uint8Array(1024 * 1024); // 1MB initial
  private arenaSize = 0; // current used size of arena

  private messageIndex: { ts: number; u: any; t: number; off: number; len: number }[] = [];
  keyframes: any[];
  maxBufferedTime: number;
  bufferReadIndex: number;

  keyframeInterval: number;
  lastKeyframeTime: number; // Last time a keyframe was stored
  currentTime: number;
  m_isPlaying: boolean;
  liveMode: boolean;
  playbackSpeed: number;
  m_recordingEnabled: boolean;
  firstCompleteTimeStep: boolean;
  firstTimeStamp: number;
  lastFrameTime: number = 0; // Last time the frame was updated
  private zstdEncoder: any = null; // optional compressor
  private static readonly ZSTD_CHUNK_SIZE = 2 * 1024 * 1024; // 10 MB chunk target
  private static readonly CHUNK_MAGIC = [0x57, 0x42, 0x5a, 0x43, 0x01]; // 'WBZC' + version(1)
  private static readonly CURRENT_SESSION_VERSION = 1; // Increment when format changes
  
  // Map of migration handlers: fromVersion -> migrate(session) returns upgraded session
  private static readonly MIGRATIONS: { [fromVersion: number]: (session: any) => any } = {
    // Example: 0 -> 1 (placeholder if an older prototype existed)
    0: (session: any) => {
      // Perform in-place or copy transformations needed to reach version 1
      session.version = 1;
      return session;
    },
    // Future migrations can be appended here, e.g. 1: (s)=>{...; s.version=2; return s;}
  };

  constructor(objectManager: ObjectManager, sceneManager: SceneManager) {
    this.objectManager = objectManager;
    this.sceneManager = sceneManager;
    
    // Compact buffer
    this.keyframes = [];       // holds full world snapshots every N seconds
    this.maxBufferedTime = 0;
    this.bufferReadIndex = 0;
    this.keyframeInterval = 2.0;
    this.lastKeyframeTime = 0; // Initialize to current time
    this.currentTime = 0;
    this.m_isPlaying = false;
    this.liveMode = true;
    this.playbackSpeed = 1;

    this.m_recordingEnabled = false;

    this.firstCompleteTimeStep = true;
    this.firstTimeStamp = -1;

    ZstdCodec.run((zstd: typeof ZstdCodec) => {
      try {
        this.zstdEncoder = new (zstd.Simple as { new(): { compress(data: Uint8Array): Uint8Array, decompress(data: Uint8Array): Uint8Array } })();
      } catch (e) {
        console.warn('Zstd encoder init failed, falling back to uncompressed binary saves.', e);
      }
    });
  }

  setWebSocketManager(webSocketManager: WebSocketManager) {
    this.webSocketManager = webSocketManager;
  }
  
  setEnableRecording(enabled: boolean) {
    this.m_recordingEnabled = enabled;
  }

  setUIManager(uiManager: UIManager | null) {
    this.uiManager = uiManager;
  }

  setPlaybackSpeed(speed: number) {
    this.playbackSpeed = speed;
  }

  getLiveMode() {
    return this.liveMode;
  }
  
  setLiveMode(live: boolean) {
    this.liveMode = live;
    if (live) 
      this.jumpToEnd();      
  }

  play() {
    
    this.m_isPlaying = true;
    this.lastFrameTime = performance.now();
  }

  isPlaying() {
    return this.m_isPlaying;
  }

  isRecordingEnabled()
  {
    return this.m_recordingEnabled
  }
  
  stop() {
    this.m_isPlaying = false;
    this.bufferReadIndex = 0;
    let time = Math.max(this.getMinBufferedTime(), Math.min(this.maxBufferedTime, 0));

    this.jumpToTime(time)
  }

  pause() {
    this.m_isPlaying = false;
  }

  getCurrentTime() {
    return this.currentTime;
  }
  
  // Return the smallest timestamp in the buffer
  getMinBufferedTime() {
    if (this.messageIndex.length === 0)
      return 0; // No messages, return 0

    else
      return this.messageIndex[0].ts; // Return the timestamp of the first message    
  }

  resetBufferState() {
    this.keyframes.length = 0;
    this.messageIndex.length = 0;
    this.arenaSize = 0;

    this.firstCompleteTimeStep = true;
    this.firstTimeStamp = -1;

    this.maxBufferedTime = 0;
    this.bufferReadIndex = 0;   
    this.currentTime = this.getMinBufferedTime();
    this.lastFrameTime = performance.now();
  }

  private parseMessage(type: any, msgArray: any[]) 
  {
    switch(type) {
      case MessageType.CREATE:
        return {
          type: type,
          uuid: msgArray[0],
          time: msgArray[1],
          geometry: msgArray[2],
          objectType: msgArray[3], 
          size: msgArray[4],
          position: msgArray[5],
          text: msgArray[6],
          name: msgArray[7]
        };

      case MessageType.CREATE_MESH:
        return {
          type: type,
          uuid: msgArray[0],
          time: msgArray[1],
          geometry: msgArray[2],
          objectType: msgArray[3], 
          vertices: msgArray[4],
          indices: msgArray[5],
          name: msgArray[6]
        };

      case MessageType.TRANSFORM:
        return {
          uuid: msgArray[0],
          time: msgArray[1],
          type: type,
          position: msgArray[2],
          rotation: msgArray[3],
        };

      case MessageType.UPDATE:
        return {
          uuid: msgArray[0],
          time: msgArray[1],
          type: type,
          size: msgArray[2],
          text: msgArray[3],
          name: msgArray[4],
        };

      case MessageType.UPDATE_MESH:
        return {
          uuid: msgArray[0],
          time: msgArray[1],
          type: type,
          vertices: msgArray[2],
          indices: msgArray[3],
          name: msgArray[4]
        };

      case MessageType.COLOR:
        return {
          uuid: msgArray[0],
          time: msgArray[1],
          color: msgArray[2],
          type: type
        };

      case MessageType.REMOVE:
        return {
          uuid: msgArray[0],
          time: msgArray[1],
          type: type,
        };

     case MessageType.CREATE_GRANULAR:
        return {
          type: type,
          uuid: msgArray[0],
          time: msgArray[1],
          position: msgArray[2],
          size: msgArray[3],
          name: msgArray[4],
          geometry: Shapes.GRANULAR,
          objectType: ObjectType.GRANULAR 
        };

      case MessageType.UPDATE_GRANULAR:
        return {
          type: type,
          uuid: msgArray[0],
          time: msgArray[1],
          position: msgArray[2],
          size: msgArray[3]
        };

      default:
        console.warn("Unknown message type:", type);
        return null; // or throw an error
    }
  }
  // Handle a received message from the WebSocket
  handleReceivedMessage(type: any, message: any) {
  
    const msg = this.parseMessage(type, message)
    if (!msg) {
      console.warn("Invalid message received:", type, message);
      return;
    }

    if (msg.time === undefined) return;

    let entry;
    const idx: number = msg.uuid;

    switch(msg.type) {

      case (MessageType.CREATE):
        entry = {
          t: msg.type,  // 0 = create
          u: idx,
          ts: msg.time,
          g: msg.geometry,
          size: msg.size,
          p: Float32Array.from(msg.position || [0, 0, 0]),
          objectType: msg.objectType,
          text: msg.text,
          name: msg.name
        };
        break;

      case (MessageType.CREATE_MESH):
        entry = {
          t: msg.type,  // 0 = create
          u: idx,
          ts: msg.time,
          vertices: msg.vertices,
          indices: msg.indices,
          g: msg.geometry,
          objectType: msg.objectType,
          name: msg.name
        };
        break;

      case (MessageType.TRANSFORM):
        entry = {
          t: msg.type,  // 1 = transform
          u: idx,
          ts: msg.time,
          p: Float32Array.from(msg.position || [0, 0, 0]),
          r: Float32Array.from(msg.rotation || [0, 0, 0, 1]),
        };
        break;

      case (MessageType.REMOVE):
        entry = {
          t: msg.type,  // 2 = remove
          u: idx,
          ts: msg.time
        };
        break;

      case (MessageType.COLOR):
        entry = {
          t: msg.type,  // 3 = color
          u: idx,
          ts: msg.time,
          c: msg.color || [1, 0, 0]
        };
        break;
        
      case (MessageType.UPDATE):
        entry = {
          t: msg.type,  
          u: idx,
          ts: msg.time,
          size: msg.size,  // Array of size elements
          text: msg.text,
          name: msg.name
          };
        break;

      case (MessageType.UPDATE_MESH):
        entry = {
          t: msg.type,  
          u: idx,
          ts: msg.time,
          vertices: msg.vertices,
          indices: msg.indices,
          name: msg.name
        };
        break;

      case (MessageType.CREATE_GRANULAR):
        entry = {
          t: msg.type,  
          u: idx,
          ts: msg.time,
          p: msg.position,
          g: Shapes.GRANULAR,
          objectType: msg.objectType,
          name: msg.name,
          size: msg.size
        };
        break;

      case (MessageType.UPDATE_GRANULAR):
        entry = {
          t: msg.type,  
          u: idx,
          ts: msg.time,
          p: msg.position,
          size: msg.size
        };
        break;

      default:
        console.log("Invalid message type: ", type, MessageType.getString(type))
    }
    if (entry) {
      this.encodeAndIndex(entry);
    }
  }

  private maybeStoreKeyframe(time: number) {
    if (!this.isRecordingEnabled()) return;

    if (this.keyframes.length == 0 ||  time - this.lastKeyframeTime >= this.keyframeInterval) {
      this.storeKeyframe(time);
    }
  }

  private storeKeyframe(time: number) {
    
    if (!this.isRecordingEnabled()) return;

    const snapshot = {
      time,
      objects: {}
    };

    for (const [uuid, object3D] of this.objectManager.objects.entries()) {
      const objectData: {
        geometry: any;
        color: unknown[];
        position: any;
        rotation: any;
        size: any;
        objectType: any;
        uuid: number;
        vertices?: any;
        indices?: any;
        text?: string;
        name?: string;
      } = {
        geometry: object3D.userData.type,
        color: object3D.userData.color ? Array.from(object3D.userData.color) : [1, 0, 0], // Ensure plain array
        //position: object3D.position ? object3D.position.toArray() : object3D.getPosition().toArray(), // .toArray() gives plain array
        position: object3D.position ? object3D.position.toArray() : undefined, // .toArray() gives plain array
        rotation: object3D.quaternion ? object3D.quaternion.toArray() : [0, 0, 0, 1], // .toArray() gives plain array
        size: object3D.userData.size || undefined,
        objectType: object3D.userData.objectType,
        uuid: uuid,
        text: object3D.userData.text || undefined,
        name: object3D.userData.name || undefined,
      };

      if ((object3D.userData.type === Shapes.MESH) || (object3D.userData.type === Shapes.HEIGHTFIELD)) {
        const mesh = object3D.children[0];
        // Type guard: check if mesh is a THREE.Mesh
        if (mesh && 'geometry' in mesh) {
          const geom = (mesh as any).geometry;
          if (geom.attributes && geom.attributes.position) {
            objectData.vertices = Array.from(geom.attributes.position.array); // Convert to plain array
          }
          const indicesAttr = geom.getIndex ? geom.getIndex() : undefined;
          if (indicesAttr) {
            objectData.indices = Array.from(indicesAttr.array); // Convert to plain array
          }
        }
      }
      (snapshot.objects as { [key: string]: typeof objectData })[uuid] = objectData;
    }
    this.keyframes.push(snapshot);
    this.lastKeyframeTime = time;
  }

  ///
  /// Return the first keyframe at or before t, or null if none
  private findNearestKeyframe(t: number) {
    
    for (let i = this.keyframes.length - 1; i >= 0; i--) {
      if (this.keyframes[i].time <= t) {
        return this.keyframes[i];
      }
    }

    // We did not find one which is before t. Then t is a too small value.
    // However if there are keyframes, we should return the first one.
    if (this.keyframes.length > 0)
      return this.keyframes[0];
    else
      return null;
  }

  private applyKeyframe(snapshot: any) {
    
    this.objectManager.resetScene();  // remove current objects
    if (this.uiManager) {
      this.uiManager.clearSidebar();
    }

    for (const [uuid, data] of Object.entries(snapshot.objects)) {
      //console.log("Applying keyframe:", uuid, data);
      const shapeData = data as {
        geometry: any;
        color: unknown[];
        position: any;
        rotation: any;
        size: any;
        objectType: any;
        uuid: number;
        vertices?: any;
        indices?: any;
        text?: any;
        name?: any;
      };

      this.objectManager.createShape(
        shapeData
      );

      // Update color
      // Update transform
      this.objectManager.transformShape(shapeData, false);
      if (!(shapeData.geometry === Shapes.MESH || shapeData.geometry === Shapes.HEIGHTFIELD))
        this.objectManager.updateShape(shapeData);

      this.objectManager.setShapeColor(shapeData);
    }
  }

  // Export a full session onto a JSON object
  private exportSession() {
    // Keyframes are prepared by storeKeyframe to have plain arrays for critical parts.

    // Process messageBuffer to ensure all data is in plain array format for JSON.stringify
    const processedMessages = this.messageIndex.map((_, i) => {
      const decoded = this.decodeEntry(i);
      // Ensure arrays (already plain) – just return shallow clone to be safe
      return { ...decoded };
    });

    const session = {
      version: PlaybackManager.CURRENT_SESSION_VERSION,
      recordedAt: new Date().toISOString(),
      keyframes: this.keyframes, // Already processed by storeKeyframe
      messages: processedMessages
    };
    return session;
  }

  saveSessionToFile() {
    const session = this.exportSession();

    const stream = new ReadableStream({
      start(controller) {
        const encoder = new TextEncoder();
        controller.enqueue(encoder.encode('{\n'));

        const keys = Object.keys(session);
        let index = 0;

        function processNextKey() {
          if (index >= keys.length) {
            controller.enqueue(encoder.encode('}\n'));
            controller.close();
            return;
          }

          const key = keys[index];
          const value = (session as Record<string, any>)[key];
          const chunk = `  "${key}": `;
          controller.enqueue(encoder.encode(chunk));

          if (Array.isArray(value)) {
            controller.enqueue(encoder.encode('[\n'));
            value.forEach((item, i) => {
              const itemChunk = `    ${JSON.stringify(item)}${i < value.length - 1 ? ',' : ''}\n`;
              controller.enqueue(encoder.encode(itemChunk));
            });
            controller.enqueue(encoder.encode('  ]'));
          } else if (typeof value === 'object' && value !== null) {
            controller.enqueue(encoder.encode('{\n'));
            const subKeys = Object.keys(value);
            subKeys.forEach((subKey, i) => {
              const subValue = value[subKey];
              const subChunk = `    "${subKey}": ${JSON.stringify(subValue)}${i < subKeys.length - 1 ? ',' : ''}\n`;
              controller.enqueue(encoder.encode(subChunk));
            });
            controller.enqueue(encoder.encode('  }'));
          } else {
            controller.enqueue(encoder.encode(`${JSON.stringify(value)}`));
          }

          controller.enqueue(encoder.encode(index < keys.length - 1 ? ',\n' : '\n'));
          index++;
          processNextKey();
        }

        processNextKey();
      }
    });

    // Consume the stream and collect chunks
    const reader = stream.getReader();
    const chunks: Uint8Array[] = [];

    function consumeStream(): Promise<void> {
      return reader.read().then(({ done, value }) => {
        if (done) {
          const blob = new Blob(chunks, { type: 'application/json' });
          const a = document.createElement('a');
          a.href = URL.createObjectURL(blob);
          a.download = 'simulation-session.json';
          document.body.appendChild(a);
          a.click();
          document.body.removeChild(a);
          return;
        }
        chunks.push(value);
        return consumeStream();
      });
    }

    consumeStream();
  }

  /**
   * Save session using MessagePack (binary) optionally compressed with Zstd.
   * This is typically 3-10x smaller than pretty JSON and far faster to serialize.
   * @param useCompression default true – requires zstd encoder successfully initialized.
   */
  saveSessionToFileBinary(useCompression: boolean = true) {
    const session = this.exportSession();
    let packed: Uint8Array;
    try {
      packed = encode(session) as Uint8Array;
    } catch (e) {
      console.error('MessagePack encode failed, aborting binary save.', e);
      return;
    }

    let data: Uint8Array = packed;
    let compressed = false;
    let chunked = false;
    if (useCompression && this.zstdEncoder) {
      try {
        if (packed.byteLength > PlaybackManager.ZSTD_CHUNK_SIZE) {
          // Chunked compression path
            const { buffer } = this.compressZstdChunked(packed);
            data = buffer;
            compressed = true;
            chunked = true;
        } else {
          // Single shot compression
          data = this.zstdEncoder.compress(packed);
          compressed = true;
        }
      } catch (e) {
        console.warn('Zstd compression failed – saving uncompressed binary.', e);
        data = packed; // fallback
      }
    }

    const ext = compressed ? (chunked ? 'wbdbg.zst' : 'wbdbg.zst') : 'wbdbg';
    const blob = new Blob([data], { type: 'application/octet-stream' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = `simulation-session.${ext}`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(a.href);

    if (compressed && !chunked) {
      const ratio = (packed.byteLength / data.byteLength).toFixed(2);
      console.log(`[SessionSave] Binary save complete. Raw=${packed.byteLength} bytes, Saved=${data.byteLength} bytes (ratio ${ratio}x).`);
    } else if (compressed && chunked) {
      console.log(`[SessionSave] Chunked binary save complete. Raw=${packed.byteLength} bytes, Container=${data.byteLength} bytes, chunks of <= ${PlaybackManager.ZSTD_CHUNK_SIZE} bytes.`);
    } else {
      console.log(`[SessionSave] Uncompressed binary save. Size=${data.byteLength} bytes.`);
    }
  }

  /**
   * Load a previously saved binary session (.wbdbg or .wbdbg.zst)
   */
  async loadSessionFromBinary(file: File) {
    try {
      const arrayBuffer = await file.arrayBuffer();
      let bytes = new Uint8Array(arrayBuffer);

      const isCompressedExt = file.name.endsWith('.zst') || file.name.endsWith('.wbdbg.zst');
      let usedChunkedContainer = false;

      // Detect chunked container (WBZC + version)
      if (this.isChunkedContainer(bytes)) {
        if (!this.zstdEncoder) {
          console.error('[SessionLoad] Zstd encoder not ready for chunked container.');
          return;
        }
        try {
          bytes = this.decompressZstdChunked(bytes);
          usedChunkedContainer = true;
        } catch (e) {
          console.error('[SessionLoad] Failed to decompress chunked container.', e);
          return;
        }
      } else if (isCompressedExt) { // legacy single-shot compressed
        if (!this.zstdEncoder) {
          console.warn('[SessionLoad] Zstd encoder not ready; attempting direct decode (may fail).');
        } else {
          try {
            bytes = this.zstdEncoder.decompress(bytes);
          } catch (e) {
            console.error('[SessionLoad] Zstd decompression failed.', e);
            return;
          }
        }
      }

      let session: any;
      try {
        session = decode(bytes);
      } catch (e) {
        // Fallback: if extension suggested compression but not chunked and we have encoder, try one more decompress attempt
        if (!usedChunkedContainer && !this.isChunkedContainer(bytes) && !isCompressedExt && this.zstdEncoder) {
          try {
            const decompressed = this.zstdEncoder.decompress(bytes);
            session = decode(decompressed);
            console.log('[SessionLoad] Decoded after fallback decompression.');
          } catch (ee) {
            console.error('[SessionLoad] MessagePack decode failed.', e, ee);
            return;
          }
        } else {
          console.error('[SessionLoad] MessagePack decode failed.', e);
          return;
        }
      }

      if (!session || typeof session !== 'object') {
        console.error('[SessionLoad] Decoded session invalid.');
        return;
      }

      // Apply migration chain (if needed)
      session = this.migrateSession(session);

      this.loadSession(session);
      console.log('[SessionLoad] Binary session loaded.', file.name, usedChunkedContainer ? '(chunked)' : '');
    } catch (err) {
      console.error('[SessionLoad] Failed to load binary session', err);
    }
  }

  private migrateSession(session: any): any {
    if (!session || typeof session !== 'object') return session;
    let v = session.version;
    if (v === undefined) {
      // Treat sessions without explicit version as version 0 (pre-versioned format)
      v = 0;
      session.version = 0;
    }

    // Apply successive migrations until reaching CURRENT_SESSION_VERSION
    while (v < PlaybackManager.CURRENT_SESSION_VERSION) {
      const migrate = PlaybackManager.MIGRATIONS[v];
      if (!migrate) {
        console.warn(`[SessionMigration] No migration path from version ${v} -> ${v + 1}. Aborting migration.`);
        break; // Leave as-is; loading may fail downstream if incompatible
      }
      try {
        session = migrate(session) || session;
      } catch (e) {
        console.error(`[SessionMigration] Migration from ${v} failed:`, e);
        break;
      }
      v = session.version;
    }

    if (v !== PlaybackManager.CURRENT_SESSION_VERSION) {
      console.warn(`[SessionMigration] Loaded session at version ${v}, expected ${PlaybackManager.CURRENT_SESSION_VERSION}. Functionality may be degraded.`);
    }
    return session;
  }

  private compressZstdChunked(raw: Uint8Array): { buffer: Uint8Array } {
    const chunkSize = PlaybackManager.ZSTD_CHUNK_SIZE;
    const numChunks = Math.ceil(raw.byteLength / chunkSize);
    const compressedChunks: {rawLen:number, comp:Uint8Array, rawSliceLen:number}[] = [];

    for (let i = 0; i < numChunks; i++) {
      const start = i * chunkSize;
      const end = Math.min(start + chunkSize, raw.byteLength);
      const slice = raw.subarray(start, end);
      const comp = this.zstdEncoder.compress(slice);
      compressedChunks.push({ rawLen: slice.byteLength, comp, rawSliceLen: slice.byteLength });
    }

    // Header: 5 bytes magic/version + 4 bytes totalRawLen + 4 bytes numChunks
    // Per chunk: 4 bytes rawLen + 4 bytes compLen + compData
    const headerSize = 5 + 4 + 4; // magic+version + totalRawLen + numChunks
    let totalSize = headerSize;
    for (const ch of compressedChunks) {
      totalSize += 4 + 4 + ch.comp.byteLength;
    }

    const out = new Uint8Array(totalSize);
    let o = 0;
    // Magic/version
    for (const m of PlaybackManager.CHUNK_MAGIC) out[o++] = m;
    const dv = new DataView(out.buffer);
    dv.setUint32(o, raw.byteLength, true); o += 4;
    dv.setUint32(o, compressedChunks.length, true); o += 4;

    for (const ch of compressedChunks) {
      dv.setUint32(o, ch.rawLen, true); o += 4;
      dv.setUint32(o, ch.comp.byteLength, true); o += 4;
      out.set(ch.comp, o); o += ch.comp.byteLength;
    }

    return { buffer: out };
  }

  private isChunkedContainer(data: Uint8Array): boolean {
    if (data.byteLength < 5) return false;
    for (let i = 0; i < PlaybackManager.CHUNK_MAGIC.length; i++) {
      if (data[i] !== PlaybackManager.CHUNK_MAGIC[i]) return false;
    }
    return true;
  }

  private decompressZstdChunked(data: Uint8Array): Uint8Array {
    if (!this.isChunkedContainer(data)) throw new Error('Not a chunked container');
    const dv = new DataView(data.buffer, data.byteOffset, data.byteLength);
    let o = 5; // skip magic/version
    const totalRaw = dv.getUint32(o, true); o += 4;
    const numChunks = dv.getUint32(o, true); o += 4;

    const out = new Uint8Array(totalRaw);
    let writeOffset = 0;
    for (let i = 0; i < numChunks; i++) {
      if (o + 8 > data.byteLength) throw new Error('Corrupt chunk header');
      const rawLen = dv.getUint32(o, true); o += 4;
      const compLen = dv.getUint32(o, true); o += 4;
      if (o + compLen > data.byteLength) throw new Error('Corrupt chunk data');
      const compSlice = data.subarray(o, o + compLen); o += compLen;
      const decompressed = this.zstdEncoder.decompress(compSlice);
      if (decompressed.byteLength !== rawLen) {
        // Accept mismatch but warn
        console.warn(`[ChunkedDecode] Raw length mismatch. Expected ${rawLen} got ${decompressed.byteLength}`);
      }
      out.set(decompressed.subarray(0, rawLen), writeOffset);
      writeOffset += rawLen;
    }
    if (writeOffset !== totalRaw) {
      console.warn(`[ChunkedDecode] Final size mismatch. Expected ${totalRaw} got ${writeOffset}`);
    }
    return out;
  }

  private replayMessagesFrom(tStart: number, tEnd: number) {
    for (let i = 0; i < this.messageIndex.length; i++) {
      const mi = this.messageIndex[i];
      if (mi.ts >= tStart && mi.ts <= tEnd) {
        const entry = this.decodeEntry(i);
        this.processMessage(entry);
        this.bufferReadIndex = i;
      }
    }
  }

  private processMessage(entry: any) {
    const uuid: number = entry.u;

    switch(entry.t)
    {
      case MessageType.CREATE:
        this.objectManager.createShape({
          uuid,
          geometry: entry.g,
          size: entry.size,
          objectType: entry.objectType,
          text: entry.text,
          name: entry.name       
        });
        break;
      case MessageType.CREATE_MESH:
        this.objectManager.createShape({
          uuid,
          geometry: entry.g,
          vertices: entry.vertices ? Array.from(entry.vertices) : undefined,
          indices: entry.indices ? Array.from(entry.indices) : undefined,
          objectType: entry.objectType,
          name: entry.name       
        });
        break;
      case MessageType.TRANSFORM:
        this.objectManager.transformShape({
          uuid,
          position: Array.from(entry.p),
          rotation: Array.from(entry.r),
        });
        break;
      case MessageType.REMOVE:
        this.objectManager.removeShape(uuid);
        break;
      case MessageType.UPDATE:
        this.objectManager.updateShape({
          uuid,
          geometry: entry.g,        
          size: entry.size,
          text: entry.text,
          name: entry.name
        });
        break;
      case MessageType.UPDATE_MESH:
        this.objectManager.updateShape({
          uuid,
          geometry: entry.g,        
          vertices: entry.vertices,
          indices: entry.indices,
          name: entry.name
        });
        break;
      case MessageType.COLOR:
        this.objectManager.setShapeColor({
          uuid,
          color: Array.from(entry.c),
        });
        break;
      case MessageType.CREATE_GRANULAR:
        this.objectManager.createShape({
          uuid,
          geometry: entry.g,
          position: entry.p ? Array.from(entry.p) : undefined,
          size: entry.size,
          objectType: entry.objectType,
          name: entry.name       
        });
        break;
      case MessageType.UPDATE_GRANULAR:
        this.objectManager.updateShape({
          uuid,
          position: entry.p,
          size: entry.size          
        });
        break;
      default:
        console.warn("Unknown message type:", entry.t, "for UUID:", uuid);
    }
  }

  // Load a session from a JSON object
  loadSession(session: any) {
    // Reset everything
    this.keyframes.length = 0;
    this.messageIndex.length = 0;
    this.arenaSize = 0;
    this.maxBufferedTime = 0;
    this.bufferReadIndex = 0;
    this.currentTime = this.getMinBufferedTime();

    // Restore session data
    for (const kf of session.keyframes || []) {
      this.keyframes.push(kf);
    }

    for (const msg of session.messages || []) {
      // Ensure legacy typed arrays converted (if any)
      this.encodeAndIndex(msg);
    }

    // Calculate maxBufferedTime safely for large arrays
    if (this.messageIndex.length > 0) {
      let maxTs = 0; // Or Number.NEGATIVE_INFINITY if timestamps can be negative
      for (let i = 0; i < this.messageIndex.length; i++) {
        const ts = this.messageIndex[i].ts || 0;
        if (ts > maxTs) {
          maxTs = ts;
        }
      }
      this.maxBufferedTime = maxTs;
    } else {
      this.maxBufferedTime = 0;
    }
    
    this.stop(); // Reset playback state
  }

  // Jump to the end of the buffered messages
  jumpToEnd() {
    this.currentTime = this.maxBufferedTime;
    
  }

  // Go forward to the next time step (all messages with the same timestamp)
  stepForward() {
    if (this.bufferReadIndex < this.messageIndex.length) {
      const mi = this.messageIndex[this.bufferReadIndex];
      this.currentTime = mi.ts;
      const entry = this.decodeEntry(this.bufferReadIndex);
      this.processMessage(entry);
      this.bufferReadIndex++;
    }
  }

  // Jump to an absolute time in seconds
  jumpToTime(t: number)
  {
    this.currentTime = Math.max(this.getMinBufferedTime(), Math.min(this.maxBufferedTime, t));
    this.m_isPlaying = false;
    this.setLiveMode(false);

    
    const keyframe = this.findNearestKeyframe(t);
    if (keyframe) {
      this.applyKeyframe(keyframe);
      this.replayMessagesFrom(keyframe.time, t);
    } else {
      this.objectManager.resetScene();
      if (this.uiManager) {
        this.uiManager.clearSidebar();
      }

      this.replayMessagesFrom(0, t);
    }  
  }

  // Go back to the previous time step (all messages with the same timestamp)
  stepBackward() 
  {
    if (this.bufferReadIndex == 0)
      return;

    this.bufferReadIndex = Math.max(this.bufferReadIndex-1, 0);
    this.currentTime = this.messageIndex[this.bufferReadIndex]?.ts ?? 0;

    // Find the first message before the current currentTime time
    while (this.bufferReadIndex > 0 && this.messageIndex[this.bufferReadIndex].ts >= this.currentTime) {
      this.bufferReadIndex--;
    }
    var timeStamp = this.messageIndex[this.bufferReadIndex];

    // Now find the first message with the same timestamp
    while (this.bufferReadIndex > 0 && this.messageIndex[this.bufferReadIndex].ts == timeStamp.ts) {
      this.bufferReadIndex--;
    }

    // Now we are at the first message with a timestamp before the current time
    var targetBufferIndex = this.bufferReadIndex; // move back
    const targetTime = this.messageIndex[targetBufferIndex]?.ts ?? 0;
    this.currentTime = targetTime;

    const keyframe = this.findNearestKeyframe(this.currentTime);
    
    if (keyframe) {
      this.applyKeyframe(keyframe);
      //this.replayMessagesFrom(this.getMinBufferedTime(), this.currentTime);
      this.replayMessagesFrom(keyframe.time, this.currentTime);
    }

    this.bufferReadIndex = targetBufferIndex; // Set the read index to the target
    this.currentTime = this.messageIndex[this.bufferReadIndex]?.ts ?? 0;
  }

  private replayUpTo(time: number): void {
    this.objectManager.resetScene(); // clears scene & objects
    this.bufferReadIndex = 0;
  
    while (
      this.bufferReadIndex < this.messageIndex.length &&
      this.messageIndex[this.bufferReadIndex].ts <= time
    ) {
      const entry = this.decodeEntry(this.bufferReadIndex);
      this.processMessage(entry);
      this.bufferReadIndex++;
    }
  }

  // Called every frame to update playback state
  updateBuffer()
  {
    const now = performance.now();
    const deltaTime = (now - this.lastFrameTime) / 1000; // in seconds
    this.lastFrameTime = now;

    if (this.liveMode) {
      this.jumpToEnd();
    }

    if (this.m_isPlaying || this.liveMode) {
      this.currentTime += deltaTime * this.playbackSpeed;

      this.currentTime = Math.min(this.currentTime, this.maxBufferedTime);
    }

    while (this.bufferReadIndex < this.messageIndex.length && this.messageIndex[this.bufferReadIndex].ts <= this.currentTime){
      const entry = this.decodeEntry(this.bufferReadIndex);
      this.processMessage(entry);

      this.bufferReadIndex++;
    }  

    // If we are recording, we should store keyframes 
    if (this.isRecordingEnabled() && this.messageIndex.length > 0)
    {
      var startTimeStamp = this.messageIndex[0].ts;
      // Save the first time stamp, but only if we have all messages for the first time step.
      // Otherwise we might save a keyFrame that is not complete.
      if (this.currentTime > startTimeStamp && this.firstTimeStamp < 0 && !this.objectManager.empty())
        this.firstTimeStamp = 0; 

      if (this.firstCompleteTimeStep && this.currentTime > this.firstTimeStamp) {
        this.firstCompleteTimeStep = false;
        this.storeKeyframe(this.currentTime);
      }
      else if (!this.objectManager.empty())
        this.maybeStoreKeyframe(this.currentTime);        
    } 
    // We have a live connection, scrap all recorded data and show just the last data
    else if (this.webSocketManager && this.webSocketManager.isConnected())
    {
      // Live mode without recording – discard buffered messages
      if (this.messageIndex.length > 0) {
        this.currentTime = this.messageIndex[this.messageIndex.length - 1].ts;
      }
      this.messageIndex.length = 0;
      this.arenaSize = 0;
      this.bufferReadIndex = 0;
      this.maxBufferedTime = 0;
    }
  }

  // Make sure we use a large enough arena for encoded messages
  private ensureArenaCapacity(extraBytes: number) {
    const needed = this.arenaSize + extraBytes;
    if (needed <= this.encodedArena.byteLength) return;
    let newCap = this.encodedArena.byteLength;
    while (newCap < needed) newCap *= 2;
    const newBuf = new Uint8Array(newCap);
    newBuf.set(this.encodedArena.subarray(0, this.arenaSize));
    this.encodedArena = newBuf;
  }

  // Encode a message and add it to the index
  private encodeAndIndex(entry: any) {
    // Normalize typed arrays to plain arrays for stable msgpack representation
    if (entry.p instanceof Float32Array) entry.p = Array.from(entry.p);
    if (entry.r instanceof Float32Array) entry.r = Array.from(entry.r);
    if (entry.c instanceof Float32Array) entry.c = Array.from(entry.c);
    const encoded = encode(entry) as Uint8Array;
    this.ensureArenaCapacity(encoded.byteLength);
    const off = this.arenaSize;
    this.encodedArena.set(encoded, off);
    this.arenaSize += encoded.byteLength;
    this.messageIndex.push({ ts: entry.ts, u: entry.u, t: entry.t, off, len: encoded.byteLength });
    this.maxBufferedTime = Math.max(this.maxBufferedTime, entry.ts);
  }

  // Decode an entry from the arena by index
  private decodeEntry(idx: number): any {
    const mi = this.messageIndex[idx];
    const slice = this.encodedArena.subarray(mi.off, mi.off + mi.len);
    return decode(slice);
  }
}