export class ObjectType {

  static RIGIDBODY = 0;
  static GEOMETRY = 1;
  static GRANULAR = 2;
  static TEXT = 3;
  static OTHER = 4;

  static typeMap = {
    RIGIDBODY: ObjectType.RIGIDBODY,
    GEOMETRY: ObjectType.GEOMETRY,
    GRANULAR: ObjectType.GRANULAR,
    TEXT: ObjectType.TEXT,
    OTHER: ObjectType.OTHER,
  };

  static stringToIndex: { [key: string]: number } = Object.entries(ObjectType.typeMap)
    .reduce((acc: { [key: string]: number }, [key, value]) => {
      acc[key.toUpperCase()] = value;
      return acc;
    }, {});

  static indexToString: { [key: number]: string } = Object.entries(ObjectType.typeMap)
    .reduce((acc: { [key: number]: string }, [key, value]) => {
      acc[value] = key.toUpperCase();
      return acc;
    }, {});

  static getIndex(name: string): number | null {
    return ObjectType.stringToIndex[name.toUpperCase()] ?? null;
  }

  static getString(index: number): string | null {
    return ObjectType.indexToString[index] ?? null;
  }
}