// Shape constants and helpers
export class Shapes {
  static SPHERE = 0;
  static BOX = 1;
  static CYLINDER = 2;
  static CAPSULE = 3;
  static CONE = 4;
  static LINE = 5;
  static PLANE = 6;
  static MESH = 7;
  static TEXT = 8;
  static HOLLOW_CYLINDER = 9;
  static HOLLOW_CONE = 10;
  static TRUNCATED_CONE = 11;
  static HEIGHTFIELD = 12;
  static WIRE = 13;
  static CONTACTS = 14;
  static RIGIDBODIES = 15;
  static GRANULAR = 16;


  static shapeMap = {
    SPHERE: Shapes.SPHERE,
    BOX: Shapes.BOX,
    CYLINDER: Shapes.CYLINDER,
    CAPSULE: Shapes.CAPSULE,
    CONE: Shapes.CONE,
    LINE: Shapes.LINE,
    PLANE: Shapes.PLANE,
    MESH: Shapes.MESH,
    TEXT: Shapes.TEXT,
    HOLLOW_CYLINDER: Shapes.HOLLOW_CYLINDER,
    HOLLOW_CONE: Shapes.HOLLOW_CONE,
    TRUNCATED_CONE: Shapes.TRUNCATED_CONE,
    HEIGHTFIELD: Shapes.HEIGHTFIELD,
    WIRE: Shapes.WIRE,
    CONTACTS: Shapes.CONTACTS,
    RIGIDBODIES: Shapes.RIGIDBODIES,
    GRANULAR: Shapes.GRANULAR
  };

  static stringToIndex = Object.entries(Shapes.shapeMap)
    .reduce((acc: { [key: string]: number }, [key, value]) => {
      acc[key.toLowerCase()] = value;
      return acc;
    }, {});

  static indexToString = Object.entries(Shapes.shapeMap)
    .reduce((acc: { [key: number]: string }, [key, value]) => {
      acc[value] = key.toLowerCase();
      return acc;
    }, {});

  static getIndex(name: string): number | null {
    return Shapes.stringToIndex[name.toLowerCase()] ?? null;
  }

  static getString(index: number): string | null {
    return Shapes.indexToString[index] ?? null;
  }
}