import * as THREE from 'three';

export class HollowCone extends THREE.Group {
  material: THREE.Material;
  topRadius: number;
  bottomRadius: number;
  height: number;
  thickness: number;
  segments: number;
  offset: number;

  /**
   * Creates a hollow truncated cone ("pipe-like" shape).
   * The group's origin is at the vertical center. A positive `offset` shifts it along +Y.
   *
   * @param {number} topRadius - Outer top radius.
   * @param {number} bottomRadius - Outer bottom radius.
   * @param {number} height - Total height.
   * @param {number} thickness - Wall thickness.
   * @param {THREE.Material} [material] - Material to apply.
   * @param {number} [segments=64] - Radial segments.
   * @param {number} [offset=0] - Vertical offset (like the OSG code).
   */
  constructor(
    topRadius: number,
    bottomRadius: number,
    height: number,
    thickness: number,
    material?: THREE.Material,
    segments: number = 64,
    offset: number = 0
  ) {
    super();

    this.material = material ?? new THREE.MeshStandardMaterial();
    this.topRadius = topRadius;
    this.bottomRadius = bottomRadius;
    this.thickness = thickness;
    this.height = height;
    this.segments = Math.max(8, Math.floor(segments));
    this.offset = offset;

    this._createGeometry();
  }

  /**
   * Creates a hollow truncated cone (pipe-like shape) using custom geometry.
   * The bottom is placed at -0.5 * height + offset, the top at 0.5 * height + offset.
   * Normals are computed for smooth shading.
   */
  private _createGeometry() {
    const topRadius = this.topRadius;
    const bottomRadius = this.bottomRadius;
    const thickness = this.thickness;
    const height = this.height;
    const segments = this.segments;
    const offset = this.offset;

    // Inner radii
    const topInnerRadius = Math.max(0, topRadius - thickness);
    const bottomInnerRadius = Math.max(0, bottomRadius - thickness);

    // Y positions
    const topY = height * 0.5 + offset;
    const bottomY = -height * 0.5 + offset;

    // Where the inner wall reaches the top (if thickness > topRadius)
    let topInnerPos = topY;
    if (topRadius < thickness) {
      const dR = bottomRadius - topRadius;
      const EPS = 1e-6;
      if (Math.abs(dR) < EPS) {
        topInnerPos = bottomY;
      } else {
        const dRdH = dR / height;
        const missing = thickness - topRadius;
        const adjusted = missing / dRdH;
        topInnerPos = Math.max(topY - adjusted, bottomY);
      }
    }

    // Generate rings
    const topOuter: number[][] = [];
    const topInner: number[][] = [];
    const bottomOuter: number[][] = [];
    const bottomInner: number[][] = [];

    for (let i = 0; i <= segments; ++i) {
      const angle = 2 * Math.PI * (i / segments);
      const cosA = Math.cos(angle);
      const sinA = Math.sin(angle);
      topOuter.push([cosA * topRadius, topY, sinA * topRadius]);
      topInner.push([cosA * topInnerRadius, topInnerPos, sinA * topInnerRadius]);
      bottomOuter.push([cosA * bottomRadius, bottomY, sinA * bottomRadius]);
      bottomInner.push([cosA * bottomInnerRadius, bottomY, sinA * bottomInnerRadius]);
    }

    // Pack vertices: bottomOuter, topOuter, bottomInner, topInner
    const vertices: number[] = [];
    bottomOuter.forEach(p => vertices.push(...p));
    topOuter.forEach(p => vertices.push(...p));
    bottomInner.forEach(p => vertices.push(...p));
    topInner.forEach(p => vertices.push(...p));

    const verticesInRing = segments + 1;
    const offTopOuter = verticesInRing;
    const offBottomInner = 2 * verticesInRing;
    const offTopInner = 3 * verticesInRing;

    // Indices
    const indices: number[] = [];

    // --- Outer mantle (fixed winding; build forward) ---
    // quad per segment: a=bottomOuter[i], b=bottomOuter[i+1], c=topOuter[i], d=topOuter[i+1]
    for (let i = 0; i < segments; ++i) {
      const a = i;
      const b = i + 1;
      const c = offTopOuter + i;
      const d = offTopOuter + i + 1;
      // CCW when viewed from outside
      indices.push(
        a, c, b,
        c, d, b
      );
    }

    // Inner mantle (faces inward; keep as-is)
    for (let i = 0; i < segments; ++i) {
      indices.push(
        offTopInner + i, offBottomInner + i, offTopInner + i + 1,
        offBottomInner + i, offBottomInner + i + 1, offTopInner + i + 1
      );
    }

    // Bottom ring (annulus)
    for (let i = 0; i < segments; ++i) {
      indices.push(
        offBottomInner + i, i, offBottomInner + i + 1,
        i, i + 1, offBottomInner + i + 1
      );
    }

    // Top: either a solid disc (if inner pinches) or a ring
    if (topRadius < thickness) {
      // Solid top disc (triangle fan)
      const centerIdx = vertices.length / 3;
      vertices.push(0, topY, 0);
      for (let i = 0; i < segments; ++i) {
        const a = offTopOuter + i;
        const b = offTopOuter + i + 1;
        // Reverse winding for inside visibility
        indices.push(centerIdx, b, a);
      }
    } else {
      // Top ring (annulus)
      for (let i = 0; i < segments; ++i) {
        const a = offTopInner + i;
        const b = offTopInner + i + 1;
        const c = offTopOuter + i;
        const d = offTopOuter + i + 1;
        // CCW when viewed from above
        indices.push(
          c, a, d,
          a, b, d
        );
      }
    }

    // Build geometry
    const geom = new THREE.BufferGeometry();
    geom.setAttribute('position', new THREE.Float32BufferAttribute(vertices, 3));
    geom.setIndex(indices);
    geom.computeVertexNormals();

    // Replace child mesh
    while (this.children.length > 0) this.remove(this.children[0]);
    const mesh = new THREE.Mesh(geom, this.material);
    this.add(mesh);

    // Wireframe overlay
    const edges = new THREE.EdgesGeometry(geom);
    const lineMaterial = new THREE.LineBasicMaterial({ color: (this.material as any).color ?? 0xffffff });
    const wireframe = new THREE.LineSegments(edges, lineMaterial);
    this.add(wireframe);
  }

  setPosition(vec3: THREE.Vector3) {
    this.position.copy(vec3);
  }

  setRotation(euler: THREE.Euler) {
    this.rotation.copy(euler);
  }

  setSize(topRadius: number,
          bottomRadius: number,
          height: number,
          thickness: number) 
  {
    // Remove all existing children (geometry meshes)
    while (this.children.length > 0) {
      const child = this.children[0];
      this.remove(child);
    }

    // Update parameters
    this.topRadius = topRadius;
    this.bottomRadius = bottomRadius;
    this.thickness = thickness;
    this.height = height; 
    // Recreate geometry
    this._createGeometry();
  }
}

