import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';
import { Shapes } from '../utils/Shapes.js';
import { ObjectManager } from './ObjectManager.js';
import { UIManager } from './UIManager.js';

///
/// Central class managing the 3D scene, camera, controls, grid, gizmo, and interactions.
///
export class SceneManager 
{
  controls!: OrbitControls;
  selectedObject: THREE.Object3D | null;
  cameraFollowOffset: THREE.Vector3;
  m_isFollowingObject: boolean;
  sceneRoot!: THREE.Group;
  private hasActiveInverseTransform: boolean = false;
  scene!: THREE.Scene;
  objectManager!: ObjectManager;
  uiManager!: UIManager;
  camera!: THREE.PerspectiveCamera;
  cameraUI!: THREE.OrthographicCamera;
  cameraGizmo!: THREE.PerspectiveCamera;
  renderer!: THREE.WebGLRenderer;
  rendererGizmo!: THREE.WebGLRenderer;
  sceneGizmo!: THREE.Scene;
  sceneUI!: THREE.Scene;
  gridHelper: THREE.GridHelper | null = null;
  gridCellSize: number = 1;
  gridTotalSize: number = 20;
  gizmoPivot!: THREE.Object3D;
  raycaster!: THREE.Raycaster;
  inverseTransform: THREE.Matrix4 = new THREE.Matrix4();
  onDblClick!: (e: MouseEvent) => void;

  private movement = {
    forward: false,
    backward: false,
    left: false,
    right: false,
    up: false,
    down: false
  };
  private movementSpeed = 0.2;
  private upAxis: string = '+Z'; // Track current up axis
  private upAxisMatrix: THREE.Matrix4 = new THREE.Matrix4(); // World->Viewer
  private upAxisMatrixInverse: THREE.Matrix4 = new THREE.Matrix4(); // Viewer->World
  private upAxisQuaternion: THREE.Quaternion = new THREE.Quaternion(); // World->Viewer
  private upAxisQuaternionInverse: THREE.Quaternion = new THREE.Quaternion(); // Viewer->World

  constructor() {
    
    this.selectedObject = null;
    this.m_isFollowingObject = false;
    this.cameraFollowOffset = new THREE.Vector3();
    this.initCamera();
    this.initGizmo();
    this.initUI();
    this.initBackground(false, false);
    // --- Add sceneRoot for up axis transforms ---
    this.sceneRoot = new THREE.Group();
    this.scene.add(this.sceneRoot);

    //this.scene.add(this.sceneRoot);
    THREE.Object3D.DEFAULT_UP.set(1, 0, 0); // X-up
    // Load grid settings from localStorage if available
    const storedCellSize = localStorage.getItem('gridCellSize');
    if (storedCellSize) {
      this.gridCellSize = parseFloat(storedCellSize) || 1;
    }
    const storedTotalSize = localStorage.getItem('gridTotalSize');
    if (storedTotalSize) {
      this.gridTotalSize = parseFloat(storedTotalSize) || 20;
    }
    this.initGrid();

    this.initKeyboardControls();
  }
  
  getInverseTransform(): THREE.Matrix4 {    
    return this.inverseTransform.clone();
  }
  
  setInverseTransform(mat: THREE.Matrix4) {    
    this.inverseTransform.copy(mat);
    this.hasActiveInverseTransform = !mat.equals(new THREE.Matrix4());
  }

  resetInverseTransform() {   
    this.inverseTransform.identity();
    this.hasActiveInverseTransform = false;
  }

  hasInverseTransform(): boolean { return this.hasActiveInverseTransform; }
  
  setUIManager(uiManager: UIManager) {
    this.uiManager = uiManager;
  }

  add(obj: THREE.Object3D) {
    this.sceneRoot.add(obj);
  }
  
  setMovementSpeed(speed: number) {
    this.movementSpeed = speed;
    localStorage.setItem('WebDebugger.settings.cameraSpeed', speed.toString());
    this.controls.zoomSpeed = this.movementSpeed * 3;
  }

  getMovementSpeed() {
    return this.movementSpeed;
  }
  
  private initKeyboardControls() {
    window.addEventListener('keydown', (e) => {
      switch (e.code) {
        case 'KeyW': this.movement.forward = true; break;
        case 'KeyS': this.movement.backward = true; break;
        case 'KeyA': this.movement.left = true; break;
        case 'KeyD': this.movement.right = true; break;
        case 'KeyQ': this.movement.down = true; break;
        case 'KeyE': this.movement.up = true; break;
      }
    });
    window.addEventListener('keyup', (e) => {
      switch (e.code) {
        case 'KeyW': this.movement.forward = false; break;
        case 'KeyS': this.movement.backward = false; break;
        case 'KeyA': this.movement.left = false; break;
        case 'KeyD': this.movement.right = false; break;
        case 'KeyQ': this.movement.down = false; break;
        case 'KeyE': this.movement.up = false; break;
      }
    });

    this.onDblClick = this.setOrbitPivotFromPointer.bind(this);
    this.renderer.domElement.addEventListener('dblclick', this.onDblClick);
  }

  /**
   * Set the up axis for the scene ('+Z', '+Y', '-Y', '+X').
   * Camera and controls always stay in Z-up. Only object data is transformed.
   * Grid/gizmo are visually rotated to match up axis.
   */
  setUpAxis(axis: string) {
    axis = axis.toUpperCase();
    this.upAxis = axis;

    this.initGizmo(axis);

    // Compute world->viewer and viewer->world matrices
    let m = new THREE.Matrix4();
    let q = new THREE.Quaternion();
    // Right handed Z up:
    if (axis === 'Z+') {
      m.identity();
      q.identity();
      
      // Left handeed Y up:
    } else if (axis === '+Y') {
      // Rotate +90 deg about X: world Y-up to viewer Z-up (fix upside-down)
      m.makeRotationX(Math.PI / 2);
      q.setFromAxisAngle(new THREE.Vector3(1, 0, 0), Math.PI / 2);
    } /*else if (axis === '-Y') {
      // Rotate -90 deg about X, then 180 deg about Z
      m.makeRotationX(-Math.PI / 2);
      m.multiply(new THREE.Matrix4().makeRotationZ(Math.PI));
      q.setFromAxisAngle(new THREE.Vector3(1, 0, 0), -Math.PI / 2);
      q.premultiply(new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0, 0, 1), Math.PI));
    }*/ 
    else if (axis === 'X+') {
      // Rotate -90 deg about Z: world X-up to viewer Z-up
      m.makeRotationZ(-Math.PI / 2);
      q.setFromAxisAngle(new THREE.Vector3(0, 0, 1), -Math.PI / 2);
    }
    else {
      console.warn('setUpAxis: Unknown axis', axis);
      m.identity();
      q.identity();
      return;
    }

    localStorage.setItem('WebDebugger.settings.upAxis', axis);

    this.upAxisMatrix.copy(m);
    this.upAxisMatrixInverse.copy(m).invert();
    this.upAxisQuaternion.copy(q);
    this.upAxisQuaternionInverse.copy(q).invert();

    // Camera and controls always Z-up
    this.camera.up.set(0, 0, 1);
    this.camera.updateProjectionMatrix();
    this.controls.update();

    // Grid: always XZ plane in viewer space (normal +Z)
    if (this.gridHelper) {
      this.gridHelper.rotation.set(Math.PI / 2, 0, 0); // XZ plane, normal +Z
    }
  }

  setObjectManager(objectManager: ObjectManager) {
    this.objectManager = objectManager;
  }

  setEnableGrid(enabled: boolean) {

    localStorage.setItem('WebDebugger.settings.grid_checkbox', enabled ? 'true' : 'false');
    if (enabled) {  
      if (!this.gridHelper) {
        this.initGrid();
      }
    } else {
      if (this.gridHelper) {
        this.sceneRoot.remove(this.gridHelper);
        this.gridHelper = null;
      }
    }
  }

  private initGrid() {
    if (this.gridHelper) this.sceneRoot.remove(this.gridHelper);
    // Calculate number of divisions (cells)
    let divisions = Math.ceil(this.gridTotalSize / this.gridCellSize);
    if (divisions < 1) divisions = 1;
    // The THREE.GridHelper size is the total size, divisions is the number of cells
    this.gridHelper = new THREE.GridHelper(this.gridTotalSize, divisions, 0x989998, 0x444444);
    this.gridHelper.rotation.x = Math.PI / 2; // Default for Z-up
    this.add(this.gridHelper);
  }

  setGrid(cellSize: number, totalSize: number) {
    if (cellSize > totalSize) return; // Ignore if cell size is greater than total size
    if (cellSize < 0.01) cellSize = 0.01;
    if (totalSize < 0.01) totalSize = 0.01;
    this.gridCellSize = cellSize;
    this.gridTotalSize = totalSize;
    localStorage.setItem('gridCellSize', String(cellSize));
    localStorage.setItem('gridTotalSize', String(totalSize));
    this.initGrid();

    localStorage.setItem('gridCellSize', cellSize.toString());
    localStorage.setItem('gridTotalSize', totalSize.toString());
  }

  initBackground(useSolid = true, storeSetting = true) {
    if (!useSolid) {
      const canvas = document.createElement('canvas');
      canvas.width = 1;
      canvas.height = 256;
      const ctx = canvas.getContext('2d');
      
      if (ctx) {
        // Create vertical gradient
        const gradient = ctx.createLinearGradient(0, 0, 0, 256);
        gradient.addColorStop(0, '#80ceea'); // top - sky blue
        gradient.addColorStop(1, '#ffffff'); // bottom - white
        
        ctx.fillStyle = gradient;
        ctx.fillRect(0, 0, 1, 256);
      }
      
      const bgTexture = new THREE.CanvasTexture(canvas);
      this.scene.background = bgTexture;  
    } else {
      this.scene.background = new THREE.Color(0x3c3c3c); // Solid Unity gray
    }

    if (storeSetting)
      localStorage.setItem('WebDebugger.settings.solid_background', useSolid ? 'true' : 'false');
  }    

  private initUI() {
    const width = window.innerWidth;
    const height = window.innerHeight;

    this.cameraUI = new THREE.OrthographicCamera(0, width, height, 0, -1, 1);
    this.sceneUI = new THREE.Scene();
  }

  updateProjectionMatrix() {
    if (this.cameraUI) {
      this.cameraUI.updateProjectionMatrix();
    }
    if (this.camera) {
      this.camera.updateProjectionMatrix();
    }
  } 

  resizeWindow(width: number, height: number) {
    const TOP_UI_OFFSET = 74; // Adjust for top UI offset
    this.cameraUI = new THREE.OrthographicCamera(0, width, height, 0, -1, 1);
    this.cameraUI.left = 0;
    this.cameraUI.right = width;
    this.cameraUI.top = height;
    this.cameraUI.bottom = 0;

    this.camera.aspect = width / (height - TOP_UI_OFFSET);
    this.renderer.setSize(width, height - TOP_UI_OFFSET);

    this.updateProjectionMatrix();
  }

  private initGizmo(axis: string = '+Z') {
    // -------------------- XYZ Gizmo --------------------
   
    if (this.rendererGizmo) {
      // Remove existing gizmo renderer if any
      document.body.removeChild(this.rendererGizmo.domElement);
    }

    this.sceneGizmo = new THREE.Scene();
    this.cameraGizmo = new THREE.PerspectiveCamera(50, 1, 0.1, 10);
    this.cameraGizmo.position.z = 2;

    this.rendererGizmo = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    this.rendererGizmo.setSize(100, 100);  // Small fixed viewport
    this.rendererGizmo.domElement.style.position = 'absolute';
    this.rendererGizmo.domElement.style.top = '40px';
    this.rendererGizmo.domElement.style.right = '140px';
    this.rendererGizmo.domElement.style.left = 'auto';
    this.rendererGizmo.domElement.style.zIndex = '10';

    document.body.appendChild(this.rendererGizmo.domElement);

    // Create a pivot to apply the inverted rotation
    this.gizmoPivot = new THREE.Object3D();
    this.sceneGizmo.add(this.gizmoPivot);

    this.raycaster = new THREE.Raycaster();

    function createAxis(parent: THREE.Object3D, color: THREE.Color, position: THREE.Vector3) {
      const cube = new THREE.Mesh(
        new THREE.BoxGeometry(0.1, 0.1, 0.1),
        new THREE.MeshBasicMaterial({ color })
      );
      cube.position.copy(position);
      parent.add(cube);

      const pointA = new THREE.Vector3(0, 0, 0); 
      const pointB = new THREE.Vector3(position.x, position.y, position.z);
      const shapeGeometry = new THREE.BufferGeometry().setFromPoints([pointA, pointB]);    
      
      const shapeMaterial = new THREE.LineBasicMaterial({ color: color });
      const line = new THREE.Line(shapeGeometry, shapeMaterial);
      parent.add(line);
    }

    let x_color = new THREE.Color().setRGB(1, 0, 0);
    let y_color = new THREE.Color().setRGB(0, 1, 0);
    let z_color = new THREE.Color().setRGB(0, 0, 1);

    let handiness = new THREE.Vector3(1, 1, 1);

    let length = 0.8;
    if (axis === '+Y')
    {
      handiness.x = -1;
      handiness.y = -1;
      x_color.setRGB(1, 0, 0);
      y_color.setRGB(0, 0, 1);
      z_color.setRGB(0, 1, 0);      
    }
    else if (axis === 'X+')
    {
      handiness.x = -1;
      x_color.setRGB(0, 0, 1);
      y_color.setRGB(0, 1, 0);
      z_color.setRGB(1, 0, 0);
    }

    createAxis(this.gizmoPivot, x_color, new THREE.Vector3(handiness.x*length, 0, 0));
    createAxis(this.gizmoPivot, y_color, new THREE.Vector3(0, handiness.y*length, 0));
    createAxis(this.gizmoPivot, z_color, new THREE.Vector3(0, 0, handiness.z*length));
  }

  remove(obj: THREE.Object3D) {
    if (!obj)
      return; 

    if (!obj.userData)
      console.warn("remove: No userData", obj);
    const isText = obj.userData.type == Shapes.TEXT;
    if (!isText)
      this.sceneRoot.remove(obj);
  }

  updateKeyboardMovement()
  {
    if (!(this.movement.forward || 
        this.movement.backward || 
        this.movement.left || 
        this.movement.right || 
        this.movement.up || 
        this.movement.down))
      return;    

    const dir = new THREE.Vector3();
    this.camera.getWorldDirection(dir);
    dir.z = 0; // Ignore vertical for WASD
    dir.normalize();

    const right = new THREE.Vector3();
    right.crossVectors(this.camera.up, dir).normalize();

    let move = new THREE.Vector3();
    if (this.movement.forward) move.add(dir);
    if (this.movement.backward) move.sub(dir);
    if (this.movement.left) move.add(right);
    if (this.movement.right) move.sub(right);
    if (this.movement.up) move.add(this.camera.up);
    if (this.movement.down) move.sub(this.camera.up);

    if (move.lengthSq() > 0) {
      move.normalize().multiplyScalar(this.movementSpeed);

      if (this.isFollowingObject()) 
      {
        this.cameraFollowOffset.add(move)
      }
      else {
        this.camera.position.add(move);
        this.controls.target.add(move);
        this.controls.update();
      }
    }
  }

  update()
  {
    // Update follow first so controls.update() applies damping from the correct target/position
    this.followObject();
    this.controls.update(); // smooth orbit / damping

    this.updateKeyboardMovement();

    this.renderer.clear();
    this.renderer.render(this.scene, this.camera);
  }

  private initCamera() {

    const TOP_UI_OFFSET = 74; // 24px main menu + 50px secondary bar
    // Compute initial rendering dimensions taking sidebar (250) & top UI offset into account
    const initialSidebarWidth = 250;
    const renderWidth = window.innerWidth - initialSidebarWidth;
    const renderHeight = window.innerHeight - TOP_UI_OFFSET;

    this.camera = new THREE.PerspectiveCamera(
      75,
      renderWidth / renderHeight,
      0.1,
      1000
    );

    // Set camera above the X-Y plane, looking toward +Z (Z-up)
    this.camera.position.set(10, 10, 10);
    this.camera.up.set(0, 0, 1);  // Z is up
    this.camera.lookAt(0, 0, 0);

    this.renderer = new THREE.WebGLRenderer({ antialias: true });
    this.renderer.setSize(renderWidth, renderHeight);
    this.renderer.autoClear = false;

    const sceneElement = document.getElementById('scene');
    if (sceneElement) {
      sceneElement.appendChild(this.renderer.domElement);
    } else {
      console.warn("Element with id 'scene' not found.");
    }

    
    // Controls
    this.controls = new OrbitControls(this.camera, this.renderer.domElement);
    this.controls.target.set(0, 0, 0);
    this.controls.update();
    this.controls.enableDamping = true; // for smooth inertia
    this.controls.dampingFactor = 0.3;
    this.controls.zoomSpeed = this.movementSpeed * 3;

    this.scene = new THREE.Scene();

    // Lighting setup for a well-lit scene
    // Ambient light for base illumination
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.9);
    this.scene.add(ambientLight);

    // Directional lights from multiple directions
    const dirLight1 = new THREE.DirectionalLight(0xffffff, 1.0);
    //dirLight1.castShadow = true;             // ✅ enable shadow casting
    //dirLight1.shadow.mapSize.width = 1024;   // Shadow quality
    //dirLight1.shadow.mapSize.height = 1024;    
    dirLight1.position.set(5, 5, 4);

    this.scene.add(dirLight1);

    const dirLight2 = new THREE.DirectionalLight(0xffffff, 1.0);
    dirLight2.position.set(-5, -5, 4);
    this.scene.add(dirLight2);

    const dirLight3 = new THREE.DirectionalLight(0xffffff, 0.3);
    dirLight3.position.set(-5, 5, 4);
    this.scene.add(dirLight3);

    // Optional: a soft point light for highlights
    const pointLight = new THREE.PointLight(0xffffff, 0.3);
    pointLight.position.set(0, 0, 5);
    this.scene.add(pointLight);
  }

  
  clear() {
    // Use helper to ensure colors/UI reset
    this.clearSelection();
    
    this.resetInverseTransform();

    this.m_isFollowingObject = false;
    this.cameraFollowOffset.set(0, 0, 0); // Reset offset

    if (this.objectManager && this.objectManager.objects) {
      for (const obj of this.objectManager.objects.values()) {
        this.remove(obj);
      }
    }

    this.objectManager.clear();
    
    // Notify UI so it can safely clear selection state
    if (this.uiManager && (this.uiManager as any).handleSceneCleared) {
      (this.uiManager as any).handleSceneCleared();
    }
  }

  setEnableFollowObject(enabled: boolean) {
    this.m_isFollowingObject = enabled;
    // Keep controls always enabled; just constrain features while following
    if (this.controls) {
      this.controls.enablePan = !enabled; // disable panning while following
    }

    if (this.isFollowingObject()) {
      const targetPosition = new THREE.Vector3();
      if (this.selectedObject) this.selectedObject.getWorldPosition(targetPosition);
      // Store the current orbit offset from the object
      this.cameraFollowOffset.subVectors(this.camera.position, targetPosition);
      // Lock orbit target to object immediately
      this.controls.target.copy(targetPosition);
    }
  }

  followObject() {
    if (!this.isFollowingObject()) return;
    if (!this.selectedObject) return;

    const objPos = new THREE.Vector3();
    this.selectedObject.getWorldPosition(objPos);

    // Capture any user-driven orbit/zoom changes since last frame (relative to previous target)
    const currentTarget = this.controls.target; // previous frame's target (object position last frame)
    const newOffset = this.camera.position.clone().sub(currentTarget);
    this.cameraFollowOffset.copy(newOffset); // persist new orbit/zoom offset

    // Lock target to the object's new position
    this.controls.target.copy(objPos);
    // Maintain camera offset relative to object
    this.camera.position.copy(objPos).add(this.cameraFollowOffset);
  }

  isFollowingObject() {
    return (this.m_isFollowingObject && this.selectedObject)
  }

  /// Select an object by its UUID, updating sidebar and highlighting in scene.
  selectObjectByUUID(uuid: number) {
    // Deselect previous sidebar item
  
    document.querySelectorAll('.tree-item.selected').forEach(el =>
      el.classList.remove('selected')
    );
  
    // Remove highlight from previously selected 3D object
    if (this.selectedObject) {
      this.selectedObject.traverse(child => {
        if ((child as THREE.Mesh).material && ((child as THREE.Mesh).material as any).originalColor) {
          ((child as THREE.Mesh).material as any).color.copy(((child as THREE.Mesh).material as any).originalColor);
        }
      });
    }
  
    // If currently following, and the selection changes (even to null), stop following.
    if (this.m_isFollowingObject) {
      this.m_isFollowingObject = false;
      this.controls.enabled = true; // Re-enable orbit controls
    }
  
    const obj = this.objectManager.get(uuid);
    if (obj) {
      this.uiManager.selectSidebarItem(uuid);
      
      obj.traverse(child => {
        if ((child as THREE.Mesh).isMesh && (child as THREE.Mesh).material && ((child as THREE.Mesh).material as any).color) {
          const mesh = child as THREE.Mesh;
          const material = mesh.material as any;
          if (!material.originalColor) {
            material.originalColor = material.color.clone();
          }
          material.color.set(0xffff00); // Yellow highlight
        }
      });
  
      this.selectedObject = obj;
      return true;
    } else {
      this.selectedObject = null;
      this.controls.enabled = true; // Ensure controls are enabled if selection is cleared
      return false;
    }
  }

  // Added: explicit clearSelection helper so UI can clear after centering
  clearSelection() {
    if (this.selectedObject) {
      // Restore original colors
      this.selectedObject.traverse(child => {
        const mesh = child as THREE.Mesh;
        if ((mesh as any).isMesh && mesh.material) {
            const mat: any = mesh.material;
            if (mat.originalColor) {
              mat.color.copy(mat.originalColor);
            }
        }
      });
    }
    this.selectedObject = null;
    if (this.m_isFollowingObject) {
      this.m_isFollowingObject = false;
      this.controls.enabled = true;
    }
    // Clear sidebar highlight
    document.querySelectorAll('.tree-item.selected').forEach(el => el.classList.remove('selected'));
    // Update UI buttons safely if available
    if (this.uiManager) {
      this.uiManager.focusBtn.disabled = true;
      this.uiManager.followCheckbox.disabled = true;
      this.uiManager.followCheckbox.checked = false;
      // Do not disable center button if an inverse transform is active
      if (!this.hasInverseTransform()) {
        this.uiManager.centerBtn.disabled = true;
        this.uiManager.centerBtn.textContent = 'Center';
      }
    }
  }

  centerCameraOnObject(obj: THREE.Object3D) {
    if (!obj) return;

    // 1. Get the object's world rotation as a quaternion
    const worldQuat = new THREE.Quaternion();
    obj.getWorldQuaternion(worldQuat);

    // 2. Invert the object's rotation and apply to sceneRoot
    this.sceneRoot.quaternion.copy(worldQuat).invert();

    // 3. Get the object's world position (center)
    const box = new THREE.Box3().setFromObject(obj);
    const center = box.getCenter(new THREE.Vector3());
    // Transform center into the parent's (scene) space, since sceneRoot is rotated
    this.sceneRoot.localToWorld(center);

    // 4. Move the camera to a fixed offset along the new +Z of the root
    // We'll use the object's bounding box size to determine a good distance
    const size = box.getSize(new THREE.Vector3()).length();
    const offset = size * 1.2 || 10;
    // The new 'up' direction is sceneRoot's local up (0,0,1) in world space
    const up = new THREE.Vector3(0, 0, 1).applyQuaternion(this.sceneRoot.quaternion);
    // The camera should look at the object from the new +Z direction
    const camPos = center.clone().add(up.clone().multiplyScalar(offset));
    this.camera.position.copy(camPos);
    this.camera.up.copy(up);
    this.camera.lookAt(center);
    this.controls.target.copy(center);
    this.controls.update();
  }



  focusCameraOnObject(obj: THREE.Object3D) {
    // If following, stop following before focusing
    if (this.m_isFollowingObject) {
      this.m_isFollowingObject = false;
      this.controls.enabled = true;
    }

    const box = new THREE.Box3().setFromObject(obj);
    const center = box.getCenter(new THREE.Vector3());
    const size = box.getSize(new THREE.Vector3()).length();
  
    const offset = size * 1.2;
    const dir = new THREE.Vector3();
    this.camera.getWorldDirection(dir);
  
    this.camera.position.copy(center.clone().add(dir.multiplyScalar(-offset)));
    this.controls.target.copy(center);
    this.controls.update();
  }
  
  resetView(){
    this.camera.position.set(10, 10, 10); // Default position
    this.controls.target.set(0, 0, 0);   // Default target
    this.camera.lookAt(0,0,0);           // Ensure camera looks at target
    this.controls.update();    
  }

  zoomToFitAll() {
    const all = Array.from(this.objectManager.objects.values());

    all.forEach(obj => {
      if (obj && obj.isObject3D) { // Ensure obj is a valid 3D object
        const box = new THREE.Box3();
        box.expandByObject(obj)
        var len = box.getSize(new THREE.Vector3()).length();
        if (isNaN(len))
          console.log("obj", obj);
      }
    });

    if (all.length === 0) {
      console.warn("zoomToFitAll: No objects in scene. Resetting camera to default view.");
      this.resetView();
      return;
    }

    const box = new THREE.Box3();
    all.forEach(obj => {
      if (obj && obj.isObject3D) { // Ensure obj is a valid 3D object
        box.expandByObject(obj);
      }
    });

    // If after iterating through all objects, the box is still empty
    if (box.isEmpty()) {
      console.warn("zoomToFitAll: Bounding box is empty after processing objects. Resetting camera.");
      this.resetView();
      return;
    }

    const center = box.getCenter(new THREE.Vector3());

    // Defensive check for NaN, though box.isEmpty() should have caught problematic scenarios.
    if (isNaN(center.x) || isNaN(center.y) || isNaN(center.z)) {
        console.error("zoomToFitAll: Calculated center is NaN despite non-empty box. Resetting camera.", center);
        this.resetView();
        return;
    }
    
    const size = box.getSize(new THREE.Vector3()).length();
    
    let effectiveOffset;
    if (size < 0.01) { // If scene is point-like or very small
      effectiveOffset = 10; // Default offset to ensure camera is not at the target
      console.log("zoomToFitAll: Scene size is very small (" + size + "), using default offset:", effectiveOffset);
    } else {
      effectiveOffset = size * 1.5;
    }
    
    console.log("zoomToFitAll - Objects:", all.length, "Center:", center, "Size:", size, "EffectiveOffset:", effectiveOffset);

    const dir = new THREE.Vector3();
    this.camera.getWorldDirection(dir); // Normalized direction camera is looking
  
    // Position camera at 'center' and move 'effectiveOffset' units backward
    // along the line of sight from the center.
    this.camera.position.copy(center).addScaledVector(dir, -effectiveOffset); 
    this.controls.target.copy(center);
    this.controls.update();
  }

  /**
  * Check if world-to-viewer transforms are needed based on current up axis.
  */
  requireWorldToViewerTransform(): boolean {
    return this.upAxis !== '+Z';
  }

  /**
   * Transform a position or direction from world (sim) to viewer (Z-up) coordinates.
   */
  worldToViewer(vec: THREE.Vector3): THREE.Vector3 {
    return vec.clone().applyMatrix4(this.upAxisMatrix);
  }

  /**
   * Transform a position or direction from viewer (Z-up) to world (sim) coordinates.
   */
  viewerToWorld(vec: THREE.Vector3): THREE.Vector3 {
    return vec.clone().applyMatrix4(this.upAxisMatrixInverse);
  }

  /**
   * Transform a quaternion from world (sim) to viewer (Z-up) coordinates.
   * This is essential for correct object orientation for all up axes.
   */
  worldToViewerQuaternion(q: THREE.Quaternion): THREE.Quaternion {
    return this.upAxisQuaternion.clone().multiply(q);
  }

  /**
   * Transform a quaternion from viewer (Z-up) to world (sim) coordinates.
   */
  viewerToWorldQuaternion(q: THREE.Quaternion): THREE.Quaternion {
    return this.upAxisQuaternionInverse.clone().multiply(q);
  }

  // the tiny sphere we’ll reuse
  private pivotMarker?: THREE.Mesh;
  private pivotMarkerHideTimeout?: number; // timeout handle for auto-hide

  private setOrbitPivotFromPointer(event: MouseEvent) {
    // 1. Convert pointer to Normalized Device Coordinates using bounding rect (robust for HiDPI & CSS scaling)
    const ndc = this.getPointerNDC(event);

    // 2. Build picking ray
    this.raycaster.setFromCamera(ndc, this.camera);

    // 3. Collect pickable objects (meshes only) – exclude helpers / gizmos / pivot marker.
    // Previous implementation used sceneRoot.traverse which still descends into children of an invisible parent,
    // causing hidden hierarchies to remain pickable. We now explicitly short‑circuit on invisible branches so any
    // object with an invisible ancestor is ignored (mirrors Raycaster's own recursive behavior when given roots).
    const pickables: THREE.Object3D[] = [];
    const gather = (obj: THREE.Object3D) => {
      if (!obj.visible) return; // prune whole subtree
      if ((obj as any).isMesh && obj !== this.pivotMarker && obj !== this.gridHelper) {
        pickables.push(obj);
      }
      for (const child of obj.children) gather(child);
    };
    gather(this.sceneRoot);

    if (!pickables.length) return;

    const hits = this.raycaster.intersectObjects(pickables, false);
    if (!hits.length) return;

    const hit = hits[0];
    const hitPoint = hit.point.clone();

    // Attempt to find the owning object that has a uuid (added by ObjectManager)
    let owner: THREE.Object3D | null = hit.object;
    while (owner && !owner.userData?.uuid && owner.parent) {
      owner = owner.parent;
    }

    if (owner && owner.userData && owner.userData.uuid) {
      // Select this object (will also clear previous selection, stop following, etc.)
      this.selectObjectByUUID(owner.userData.uuid);
      this.setEnableFollowObject(this.uiManager.followCheckbox.checked);
    }

    const oldTarget = this.controls.target.clone();
    const offset = this.camera.position.clone().sub(oldTarget);

    this.controls.target.copy(hitPoint);
    // Intentionally not moving camera position
    this.controls.update();

    this.showPivotMarker(hitPoint);
  }

  private showPivotMarker(p: THREE.Vector3) {
    if (!this.pivotMarker) {
      const geom = new THREE.SphereGeometry(0.1, 16, 12); // small
      const mat = new THREE.MeshBasicMaterial({
        color: 0xff4081,
        depthTest: false,
        transparent: true,
        opacity: 0.9
      });
      this.pivotMarker = new THREE.Mesh(geom, mat);
      this.pivotMarker.renderOrder = 999;
      this.scene.add(this.pivotMarker); // add to root so it stays independent of sceneRoot rotation intent
    }

    // Scale with distance to keep roughly consistent on-screen size
    const dist = this.camera.position.distanceTo(p);
    const size = THREE.MathUtils.clamp(dist * 0.03, 0.03, 2.0);
    this.pivotMarker.scale.setScalar(size);

    this.pivotMarker.position.copy(p);
    this.pivotMarker.visible = true;

    // Reset any previous hide timer
    if (this.pivotMarkerHideTimeout !== undefined) {
      clearTimeout(this.pivotMarkerHideTimeout);
    }
    this.pivotMarkerHideTimeout = window.setTimeout(() => {
      if (this.pivotMarker) {
        this.pivotMarker.visible = false;
      }
    }, 3000);
  }

  private getPointerNDC(event: MouseEvent): THREE.Vector2 {
    const canvas = this.renderer.domElement;
    const rect = canvas.getBoundingClientRect();
    const x = (event.clientX - rect.left) / rect.width;
    const y = (event.clientY - rect.top) / rect.height;
    return new THREE.Vector2(x * 2 - 1, -(y * 2 - 1));
  }
}


