import * as THREE from 'three';

export class TruncatedCone extends THREE.Group {
  material: THREE.Material;
  topRadius: number;
  bottomRadius: number;
  height: number;
  segments: number;

  /**
   * Creates a Truncated solid cone .
   * The group's origin is at the vertical center. A positive `offset` shifts it along +Y.
   *
   * @param {number} topRadius - Outer top radius.
   * @param {number} bottomRadius - Outer bottom radius.
   * @param {number} height - Total height.
   * @param {THREE.Material} [material] - Material to apply.
   * @param {number} [segments=64] - Radial segments.
   * @param {number} [offset=0] - Vertical offset (like the OSG code).
   */
  constructor(bottomRadius: number, topRadius: number, height: number, material?: THREE.Material, segments: number = 64) {
    super();
    this.bottomRadius = bottomRadius;
    this.topRadius = topRadius;
    this.height = height;
    this.segments = segments;
    this.material = material || new THREE.MeshStandardMaterial({ color: 0x888888 });
    this._createGeometry();
  }

  /**
   * Creates a solid truncated cone matching the OSG C++ implementation.
   * The bottom is at y=0, the top at y=height. Axis is +Y.
   */
  private _createGeometry() {
    const topRadius = this.topRadius;
    const bottomRadius = this.bottomRadius;
    const height = this.height;
    const segments = this.segments;

    const numSegments = Math.max(3, segments);
    const verticesInRing = numSegments + 1;
    const delta = (2 * Math.PI) / numSegments;

    // Build rings; note: angle decreases → ring is clockwise when seen from above.
    const topOuter: number[][] = [];
    const bottomOuter: number[][] = [];
    let angle = 0.0;
    for (let i = 0; i < numSegments; ++i, angle -= delta) {
      const cosA = Math.cos(angle);
      const sinA = Math.sin(angle);
      topOuter.push([cosA * topRadius, height, sinA * topRadius]);
      bottomOuter.push([cosA * bottomRadius, 0, sinA * bottomRadius]);
    }
    // Duplicate first vertex at end for a closed ring
    topOuter.push([...topOuter[0]]);
    bottomOuter.push([...bottomOuter[0]]);

    // Pack vertices: bottomOuter, topOuter, bottom center, top center
    const vertices: number[] = [];
    bottomOuter.forEach(p => vertices.push(...p));
    topOuter.forEach(p => vertices.push(...p));
    const idxBottomCenter = vertices.length / 3; vertices.push(0, 0, 0);
    const idxTopCenter    = vertices.length / 3; vertices.push(0, height, 0);

    const offsetTopOuter = verticesInRing;

    // Build indices (all triangles)
    const indices: number[] = [];

    // --- Mantle (two triangles per quad), CCW from the outside ---
    for (let i = 0; i < verticesInRing - 1; ++i) {
      const a = offsetTopOuter + i;     // top i
      const b = i;                      // bottom i
      const c = offsetTopOuter + i + 1; // top i+1
      const d = i + 1;                  // bottom i+1
      indices.push(a, b, d);
      indices.push(a, d, c);
    }

    // --- Top disc (triangle fan) ---
    // Reverse order so top cap is CW when viewed from above (front faces down)
    for (let i = 1; i < verticesInRing; ++i) {
      indices.push(idxTopCenter, offsetTopOuter + i - 1, offsetTopOuter + i);
    }

    // --- Bottom disc (triangle fan) ---
    // For the bottom, CCW front faces are seen from below; this order is correct.
    for (let i = 1; i < verticesInRing; ++i) {
      indices.push(idxBottomCenter, i, i - 1);
    }

    // Build geometry
    const geom = new THREE.BufferGeometry();
    geom.setAttribute("position", new THREE.Float32BufferAttribute(vertices, 3));
    geom.setIndex(indices);
    geom.computeVertexNormals();

    // Mesh + wireframe overlay
    const mesh = new THREE.Mesh(geom, this.material);
    this.add(mesh);

    const edges = new THREE.EdgesGeometry(geom);
    const lineMaterial = new THREE.LineBasicMaterial({ color: (this.material as any).color ?? 0xffffff });
    const wireframe = new THREE.LineSegments(edges, lineMaterial);

    this.add(wireframe);
  }

  setPosition(vec3: THREE.Vector3) {
    this.position.copy(vec3);
  }

  setRotation(euler: THREE.Euler) {
    this.rotation.copy(euler);
  }

  setSize(topRadius: number,
          bottomRadius: number,
          height: number) 
  {
    // Remove all existing children (geometry meshes)
    while (this.children.length > 0) {
      const child = this.children[0];
      this.remove(child);
    }

    // Update parameters
    this.topRadius = topRadius;
    this.bottomRadius = bottomRadius;
    this.height = height; 
 
    // Recreate geometry
    this._createGeometry();
  }
}

